-- AC Project production database schema (PROPOSED, DOC 0.28.0, IR118)
-- Target: Amazon Aurora PostgreSQL 16 (ap-southeast-5). Design: docs/02-design/database-design.md
-- Conventions
--   * One schema per Core API module; a module only touches its own schema (database-design.md §2).
--   * Every business table carries tenant_id and is protected by row-level security (RLS) on
--     current_setting('app.tenant_id'), set with SET LOCAL by the Go transaction manager.
--   * IDs are UUIDv7 generated by the application; gen_random_uuid() is only a fallback default.
--   * Optimistic concurrency: version int, UPDATE ... WHERE id = $1 AND version = $2 (0 rows = CONFLICT).
--   * Enumerations are text + CHECK (cheap to extend with a migration); money is bigint minor units + currency.
--   * Value objects that are always read and written whole are jsonb; anything filtered, joined or
--     updated on its own is a column or a child table.

CREATE EXTENSION IF NOT EXISTS citext;
CREATE EXTENSION IF NOT EXISTS pgcrypto;
CREATE EXTENSION IF NOT EXISTS btree_gist;

CREATE SCHEMA IF NOT EXISTS platform;
CREATE SCHEMA IF NOT EXISTS identity;
CREATE SCHEMA IF NOT EXISTS assets;
CREATE SCHEMA IF NOT EXISTS devices;
CREATE SCHEMA IF NOT EXISTS control;
CREATE SCHEMA IF NOT EXISTS monitoring;
CREATE SCHEMA IF NOT EXISTS maintenance;
CREATE SCHEMA IF NOT EXISTS billing;
CREATE SCHEMA IF NOT EXISTS restrictions;
CREATE SCHEMA IF NOT EXISTS energy;
CREATE SCHEMA IF NOT EXISTS notify;
CREATE SCHEMA IF NOT EXISTS audit;

-- Business time of the current transaction: the API sets app.now to the request clock (demo scenario clock in the demo
-- environment, IR157); without it the database time is used.
CREATE FUNCTION platform.app_now() RETURNS timestamptz LANGUAGE sql STABLE AS $$
  SELECT COALESCE(NULLIF(current_setting('app.now', true), '')::timestamptz, now())
$$;

-- ---------------------------------------------------------------------------------------------
-- platform: tenants, outbox, idempotency, scheduler leases (shared infrastructure, not a module)
-- ---------------------------------------------------------------------------------------------
CREATE TABLE platform.tenants (
  id          uuid PRIMARY KEY DEFAULT gen_random_uuid(),
  name        text NOT NULL,
  status      text NOT NULL DEFAULT 'active' CHECK (status IN ('active','inactive')),
  created_at  timestamptz NOT NULL DEFAULT platform.app_now()
);

CREATE TABLE platform.outbox (
  id             uuid PRIMARY KEY DEFAULT gen_random_uuid(),
  tenant_id      uuid NOT NULL REFERENCES platform.tenants(id),
  aggregate_type text NOT NULL,
  aggregate_id   uuid NOT NULL,
  event_type     text NOT NULL,
  payload        jsonb NOT NULL,
  correlation_id text NOT NULL,
  occurred_at    timestamptz NOT NULL DEFAULT platform.app_now(),
  published_at   timestamptz,
  attempts       int NOT NULL DEFAULT 0,
  last_error     text,
  seq            bigint GENERATED ALWAYS AS IDENTITY UNIQUE  -- commit-independent order for consumers (IR183)
);
CREATE INDEX outbox_unpublished ON platform.outbox (occurred_at) WHERE published_at IS NULL;
CREATE INDEX outbox_type_seq ON platform.outbox (event_type, seq);  -- consumers poll their event types in order

-- Generic change capture (IR188): AFTER row triggers publish RowChanged:<schema>.<table> {op, row} with the columns
-- named in the trigger arguments. Consuming services keep reference copies (<schema>.ref_<table>) of exactly those
-- columns instead of reading the owner's tables; the owner's write paths need no changes.
CREATE FUNCTION platform.capture_row() RETURNS trigger LANGUAGE plpgsql AS $$
DECLARE
  src jsonb;
  row jsonb := '{}';
  col text;
  source text;
BEGIN
  -- partitions report the partitioned table (root) as the source
  SELECT n.nspname || '.' || c.relname INTO source FROM pg_class c JOIN pg_namespace n ON n.oid = c.relnamespace
    WHERE c.oid = COALESCE(pg_partition_root(TG_RELID), TG_RELID);
  IF TG_OP = 'DELETE' THEN src := to_jsonb(OLD); ELSE src := to_jsonb(NEW); END IF;
  FOREACH col IN ARRAY TG_ARGV LOOP
    row := row || jsonb_build_object(col, src -> col);
  END LOOP;
  INSERT INTO platform.outbox (tenant_id, aggregate_type, aggregate_id, event_type, payload, correlation_id)
    VALUES ((src ->> 'tenant_id')::uuid, split_part(source, '.', 2), COALESCE((src ->> 'id')::uuid, (src ->> 'restriction_id')::uuid, gen_random_uuid()),
            'RowChanged:' || source, jsonb_build_object('op', TG_OP, 'row', row), 'change-capture');
  RETURN NULL;
END $$;

CREATE TABLE platform.idempotency_keys (
  tenant_id      uuid NOT NULL REFERENCES platform.tenants(id),
  membership_id  uuid NOT NULL,
  key            text NOT NULL CHECK (length(key) BETWEEN 8 AND 128),
  operation      text NOT NULL,
  request_hash   bytea NOT NULL,
  status         text NOT NULL CHECK (status IN ('in_progress','completed')),
  http_status    int,
  response       jsonb,
  created_at     timestamptz NOT NULL DEFAULT platform.app_now(),
  expires_at     timestamptz NOT NULL DEFAULT platform.app_now() + interval '24 hours',
  PRIMARY KEY (tenant_id, membership_id, key)
);
CREATE INDEX idempotency_expiry ON platform.idempotency_keys (expires_at);

CREATE TABLE platform.scheduled_items (
  id           uuid PRIMARY KEY DEFAULT gen_random_uuid(),
  tenant_id    uuid NOT NULL REFERENCES platform.tenants(id),
  kind         text NOT NULL,           -- e.g. restriction_execute, offer_expiry, job_auto_confirm (backend-architecture §10)
  target_type  text NOT NULL,
  target_id    uuid NOT NULL,
  due_at       timestamptz NOT NULL,
  lease_owner  text,
  lease_until  timestamptz,
  attempts     int NOT NULL DEFAULT 0,
  done_at      timestamptz,
  cancelled_at timestamptz,
  last_error   text,
  UNIQUE (kind, target_id, due_at)
);
CREATE INDEX scheduled_due ON platform.scheduled_items (due_at) WHERE done_at IS NULL AND cancelled_at IS NULL;

CREATE TABLE platform.processed_events (       -- consumer-side de-duplication (at-least-once delivery)
  consumer     text NOT NULL,
  event_id     uuid NOT NULL,
  processed_at timestamptz NOT NULL DEFAULT platform.app_now(),
  PRIMARY KEY (consumer, event_id)
);

CREATE TABLE platform.stream_checkpoints (     -- Kinesis shard checkpoints for the telemetry worker
  stream_name     text NOT NULL,
  shard_id        text NOT NULL,
  sequence_number text NOT NULL,
  lease_owner     text,
  lease_until     timestamptz,
  updated_at      timestamptz NOT NULL DEFAULT platform.app_now(),
  PRIMARY KEY (stream_name, shard_id)
);

CREATE TABLE platform.demo_clock (             -- demo environment only (DEMO_OPS): scenario clock shared by API and workers (IR168)
  id         boolean PRIMARY KEY DEFAULT true CHECK (id),   -- single row
  offset_ms  bigint NOT NULL,                  -- scenario time minus wall-clock time
  updated_at timestamptz NOT NULL DEFAULT now()
);

-- ---------------------------------------------------------------------------------------------
-- identity
-- ---------------------------------------------------------------------------------------------
CREATE TABLE identity.permissions (           -- reference data: the 38 Permission values (IR107)
  code        text PRIMARY KEY,
  resource    text NOT NULL,
  kind        text NOT NULL CHECK (kind IN ('read','write','action'))
);

CREATE TABLE identity.users (
  id            uuid PRIMARY KEY DEFAULT gen_random_uuid(),
  cognito_sub   text UNIQUE,
  email         citext NOT NULL UNIQUE,
  display_name  text NOT NULL CHECK (length(display_name) BETWEEN 1 AND 120),
  phone         text,
  status        text NOT NULL DEFAULT 'active' CHECK (status IN ('invited','active','disabled','anonymised')),
  last_sign_in_at timestamptz,
  created_at    timestamptz NOT NULL DEFAULT platform.app_now(),
  updated_at    timestamptz NOT NULL DEFAULT platform.app_now(),
  version       int NOT NULL DEFAULT 1
);

CREATE TABLE identity.organizations (
  id          uuid PRIMARY KEY DEFAULT gen_random_uuid(),
  tenant_id   uuid NOT NULL REFERENCES platform.tenants(id),
  name        text NOT NULL,
  kind        text NOT NULL CHECK (kind IN ('customer','contractor','operator')),
  status      text NOT NULL DEFAULT 'active' CHECK (status IN ('active','inactive')),
  version     int NOT NULL DEFAULT 1,
  created_at  timestamptz NOT NULL DEFAULT platform.app_now(),
  updated_at  timestamptz NOT NULL DEFAULT platform.app_now(),
  UNIQUE (tenant_id, id)
);

CREATE TABLE identity.memberships (
  id              uuid PRIMARY KEY DEFAULT gen_random_uuid(),
  tenant_id       uuid NOT NULL REFERENCES platform.tenants(id),
  user_id         uuid NOT NULL REFERENCES identity.users(id),
  organization_id uuid NOT NULL,
  role            text NOT NULL CHECK (role IN ('client','contractor','technician','admin')),
  employment      text CHECK (employment IN ('internal','external')),
  client_role     text CHECK (client_role IN ('owner','member')),
  scope_version   int NOT NULL DEFAULT 1,
  valid_from      timestamptz NOT NULL,
  valid_until     timestamptz,
  version         int NOT NULL DEFAULT 1,
  created_at      timestamptz NOT NULL DEFAULT platform.app_now(),
  updated_at      timestamptz NOT NULL DEFAULT platform.app_now(),
  FOREIGN KEY (tenant_id, organization_id) REFERENCES identity.organizations(tenant_id, id),
  CHECK (valid_until IS NULL OR valid_until > valid_from),
  CHECK ((role = 'client') = (client_role IS NOT NULL)),
  CHECK (role <> 'technician' OR employment IS NOT NULL),
  CHECK (NOT (role = 'technician' AND employment = 'external') OR valid_until IS NOT NULL),   -- external end date required (FR-A03)
  UNIQUE (tenant_id, id)
);
CREATE INDEX memberships_user ON identity.memberships (user_id);
CREATE INDEX memberships_org ON identity.memberships (tenant_id, organization_id);

CREATE TABLE identity.membership_permissions (
  tenant_id     uuid NOT NULL,
  membership_id uuid NOT NULL,
  permission    text NOT NULL REFERENCES identity.permissions(code),
  PRIMARY KEY (membership_id, permission),
  FOREIGN KEY (tenant_id, membership_id) REFERENCES identity.memberships(tenant_id, id) ON DELETE CASCADE
);

CREATE TABLE identity.membership_scopes (
  tenant_id     uuid NOT NULL,
  membership_id uuid NOT NULL,
  kind          text NOT NULL CHECK (kind IN ('tenant','organization','property','unit')),
  ref_id        uuid NOT NULL,
  PRIMARY KEY (membership_id, kind, ref_id),
  FOREIGN KEY (tenant_id, membership_id) REFERENCES identity.memberships(tenant_id, id) ON DELETE CASCADE
);
CREATE INDEX membership_scopes_ref ON identity.membership_scopes (tenant_id, kind, ref_id);

CREATE TABLE identity.qualification_grants (
  id            uuid PRIMARY KEY DEFAULT gen_random_uuid(),
  tenant_id     uuid NOT NULL,
  membership_id uuid NOT NULL,
  code          text NOT NULL,
  valid_from    timestamptz NOT NULL,
  valid_until   timestamptz NOT NULL,
  revoked_at    timestamptz,
  FOREIGN KEY (tenant_id, membership_id) REFERENCES identity.memberships(tenant_id, id) ON DELETE CASCADE,
  CHECK (valid_until > valid_from)
);
CREATE INDEX qualification_grants_membership ON identity.qualification_grants (membership_id);

CREATE TABLE identity.preferences (
  user_id               uuid PRIMARY KEY REFERENCES identity.users(id),
  locale                text NOT NULL DEFAULT 'en' CHECK (locale IN ('en','ms')),
  timezone              text NOT NULL DEFAULT 'Asia/Kuala_Lumpur',
  currency              char(3) NOT NULL DEFAULT 'MYR' CHECK (currency = 'MYR'),
  monthly_report_email  boolean NOT NULL DEFAULT false,
  channels              text[] NOT NULL DEFAULT '{inApp}',
  version               int NOT NULL DEFAULT 1,
  updated_at            timestamptz NOT NULL DEFAULT platform.app_now()
);

CREATE TABLE identity.two_factor (             -- FR-X08 demo two-step verification (IR112, IR144)
  user_id              uuid PRIMARY KEY REFERENCES identity.users(id),
  enabled_at           timestamptz NOT NULL,
  recovery_code_hashes text[] NOT NULL CHECK (cardinality(recovery_code_hashes) <= 8),
  version              int NOT NULL DEFAULT 1,
  updated_at           timestamptz NOT NULL DEFAULT platform.app_now()
);

CREATE TABLE identity.consents (
  id            uuid PRIMARY KEY DEFAULT gen_random_uuid(),
  tenant_id     uuid NOT NULL,
  membership_id uuid NOT NULL,
  purpose       text NOT NULL CHECK (purpose IN ('location_automation')),
  granted       boolean NOT NULL,
  granted_at    timestamptz,
  revoked_at    timestamptz,
  version       int NOT NULL DEFAULT 1,
  created_at    timestamptz NOT NULL DEFAULT platform.app_now(),
  updated_at    timestamptz NOT NULL DEFAULT platform.app_now(),
  FOREIGN KEY (tenant_id, membership_id) REFERENCES identity.memberships(tenant_id, id),
  UNIQUE (membership_id, purpose)
);

CREATE TABLE identity.client_users (           -- customer-side user list and invites (FR-A17, FR-C19)
  id                       uuid PRIMARY KEY DEFAULT gen_random_uuid(),
  tenant_id                uuid NOT NULL,
  customer_id              uuid NOT NULL,
  membership_id            uuid,
  email                    citext NOT NULL,
  display_name             text,
  client_role              text NOT NULL CHECK (client_role IN ('owner','member')),
  status                   text NOT NULL CHECK (status IN ('invited','active','disabled')),
  allowed_channels         text[] NOT NULL DEFAULT '{inApp,email}',
  invited_at               timestamptz NOT NULL,
  invited_by_membership_id uuid NOT NULL,
  last_invite_sent_at      timestamptz,
  version                  int NOT NULL DEFAULT 1,
  created_at               timestamptz NOT NULL DEFAULT platform.app_now(),
  updated_at               timestamptz NOT NULL DEFAULT platform.app_now(),
  UNIQUE (tenant_id, customer_id, email)
);

-- ---------------------------------------------------------------------------------------------
-- assets
-- ---------------------------------------------------------------------------------------------
CREATE TABLE assets.customers (
  id              uuid PRIMARY KEY DEFAULT gen_random_uuid(),
  tenant_id       uuid NOT NULL REFERENCES platform.tenants(id),
  organization_id uuid NOT NULL UNIQUE,
  name            text NOT NULL,
  status          text NOT NULL DEFAULT 'active' CHECK (status IN ('active','inactive')),
  service_profile text NOT NULL CHECK (service_profile IN ('rto','general','energy','environment')),
  version         int NOT NULL DEFAULT 1,
  created_at      timestamptz NOT NULL DEFAULT platform.app_now(),
  updated_at      timestamptz NOT NULL DEFAULT platform.app_now(),
  UNIQUE (tenant_id, id)
);

CREATE TABLE assets.properties (
  id                  uuid PRIMARY KEY DEFAULT gen_random_uuid(),
  tenant_id           uuid NOT NULL,
  customer_org_id     uuid NOT NULL,
  kind                text NOT NULL CHECK (kind IN ('home','office')),
  name                text NOT NULL CHECK (length(name) BETWEEN 1 AND 120),
  address             text,
  access_instructions text,
  archived            boolean NOT NULL DEFAULT false,
  version             int NOT NULL DEFAULT 1,
  created_at          timestamptz NOT NULL DEFAULT platform.app_now(),
  updated_at          timestamptz NOT NULL DEFAULT platform.app_now(),
  UNIQUE (tenant_id, id)
);
CREATE INDEX properties_customer ON assets.properties (tenant_id, customer_org_id) WHERE NOT archived;
CREATE UNIQUE INDEX properties_name ON assets.properties (tenant_id, customer_org_id, lower(name)) WHERE NOT archived;

CREATE TABLE assets.spaces (
  id              uuid PRIMARY KEY DEFAULT gen_random_uuid(),
  tenant_id       uuid NOT NULL,
  property_id     uuid NOT NULL,
  parent_space_id uuid,
  kind            text NOT NULL CHECK (kind IN ('area','floor','room','space')),
  name            text NOT NULL CHECK (length(name) BETWEEN 1 AND 120),
  archived        boolean NOT NULL DEFAULT false,
  version         int NOT NULL DEFAULT 1,
  created_at      timestamptz NOT NULL DEFAULT platform.app_now(),
  updated_at      timestamptz NOT NULL DEFAULT platform.app_now(),
  FOREIGN KEY (tenant_id, property_id) REFERENCES assets.properties(tenant_id, id),
  UNIQUE (tenant_id, id)
);
ALTER TABLE assets.spaces ADD FOREIGN KEY (tenant_id, parent_space_id) REFERENCES assets.spaces(tenant_id, id);
CREATE INDEX spaces_property ON assets.spaces (tenant_id, property_id) WHERE NOT archived;
CREATE UNIQUE INDEX spaces_name ON assets.spaces (tenant_id, property_id, coalesce(parent_space_id, '00000000-0000-0000-0000-000000000000'::uuid), lower(name)) WHERE NOT archived;

CREATE TABLE assets.units (                      -- ACUnit
  id                  uuid PRIMARY KEY DEFAULT gen_random_uuid(),
  tenant_id           uuid NOT NULL,
  customer_org_id     uuid NOT NULL,
  property_id         uuid NOT NULL,
  space_id            uuid,
  display_name        text NOT NULL CHECK (length(display_name) BETWEEN 1 AND 120),
  model_id            uuid NOT NULL,             -- devices.capabilities.id (other module: no FK)
  type                text NOT NULL DEFAULT 'split' CHECK (type = 'split'),
  installed_at        timestamptz,
  service_scope       text[] NOT NULL DEFAULT '{indoor,outdoor,electrical}',
  warranty_ends_at    timestamptz,
  archived            boolean NOT NULL DEFAULT false,
  capability_version  int NOT NULL,
  -- Repository-derived read model (written by Devices / Control events, IR47)
  connection          text NOT NULL DEFAULT 'unknown' CHECK (connection IN ('online','offline','unknown','connecting','error')),
  observed_state      jsonb NOT NULL DEFAULT '{"power":null,"celsius":null,"mode":null,"fanLevel":null,"observedAt":null}',
  observed_restriction jsonb,
  last_seen_at        timestamptz,
  version             int NOT NULL DEFAULT 1,
  created_at          timestamptz NOT NULL DEFAULT platform.app_now(),
  updated_at          timestamptz NOT NULL DEFAULT platform.app_now(),
  FOREIGN KEY (tenant_id, property_id) REFERENCES assets.properties(tenant_id, id),
  FOREIGN KEY (tenant_id, space_id) REFERENCES assets.spaces(tenant_id, id),
  UNIQUE (tenant_id, id)
);
CREATE INDEX units_customer ON assets.units (tenant_id, customer_org_id) WHERE NOT archived;
CREATE INDEX units_property ON assets.units (tenant_id, property_id, space_id) WHERE NOT archived;
CREATE INDEX units_connection ON assets.units (tenant_id, connection) WHERE NOT archived;

CREATE TABLE assets.unit_alert_policies (        -- units carry policies (IR108); default policy is implicit
  tenant_id  uuid NOT NULL,
  unit_id    uuid NOT NULL,
  policy_id  uuid NOT NULL,                      -- monitoring.alert_policies.id
  attached_at timestamptz NOT NULL DEFAULT platform.app_now(),
  PRIMARY KEY (unit_id, policy_id),
  FOREIGN KEY (tenant_id, unit_id) REFERENCES assets.units(tenant_id, id)
);
CREATE INDEX unit_alert_policies_policy ON assets.unit_alert_policies (tenant_id, policy_id);

CREATE TABLE assets.unit_import_previews (       -- FR-A18 preview store: 30-minute validation result, no business data
  id           uuid PRIMARY KEY DEFAULT gen_random_uuid(),
  tenant_id    uuid NOT NULL,
  customer_id  uuid NOT NULL,
  membership_id uuid NOT NULL,
  file_name    text NOT NULL CHECK (length(file_name) BETWEEN 1 AND 200),
  rows         jsonb NOT NULL,                    -- ImportRow[] with resolved ids
  expires_at   timestamptz NOT NULL,
  created_at   timestamptz NOT NULL DEFAULT platform.app_now()
);
CREATE INDEX unit_import_previews_expiry ON assets.unit_import_previews (expires_at);

CREATE TABLE assets.unit_imports (               -- FR-A18
  id                   uuid PRIMARY KEY DEFAULT gen_random_uuid(),
  tenant_id            uuid NOT NULL,
  customer_id          uuid NOT NULL,
  preview_id           uuid NOT NULL,
  source_object_key    text NOT NULL,             -- S3 key of the uploaded CSV
  created_property_ids uuid[] NOT NULL DEFAULT '{}',
  created_space_ids    uuid[] NOT NULL DEFAULT '{}',
  created_unit_ids     uuid[] NOT NULL DEFAULT '{}',
  skipped_row_numbers  int[] NOT NULL DEFAULT '{}',
  undo_until           timestamptz NOT NULL,
  state                text NOT NULL CHECK (state IN ('imported','undone')),
  version              int NOT NULL DEFAULT 1,
  created_at           timestamptz NOT NULL DEFAULT platform.app_now(),
  updated_at           timestamptz NOT NULL DEFAULT platform.app_now()
);

-- Projections of maintenance access owned by equipment (IR186): fed by OfferAccessChanged / AssignmentAccessChanged
-- events, read by the unit scope (IR169/IR170) instead of maintenance tables.
CREATE TABLE assets.unit_offer_access (           -- accepted Offers: contractor access windows per unit
  tenant_id          uuid NOT NULL,
  offer_id           uuid NOT NULL,
  job_id             uuid NOT NULL,
  unit_id            uuid NOT NULL,
  contractor_org_id  uuid NOT NULL,
  access_valid_from  timestamptz NOT NULL,
  access_valid_until timestamptz NOT NULL,
  PRIMARY KEY (tenant_id, offer_id)
);
CREATE INDEX unit_offer_access_unit ON assets.unit_offer_access (tenant_id, unit_id);

CREATE TABLE assets.unit_assignment_access (      -- Assignments: technician viewing and work windows per unit (revoked kept, IR187)
  tenant_id                uuid NOT NULL,
  assignment_id            uuid NOT NULL,
  job_id                   uuid NOT NULL,
  unit_id                  uuid NOT NULL,
  technician_membership_id uuid NOT NULL,
  created_at               timestamptz NOT NULL,
  scheduled                tstzrange NOT NULL,
  active                   boolean NOT NULL,      -- status = 'active'; revoked rows keep diagnostic-run visibility (IR139)
  PRIMARY KEY (tenant_id, assignment_id)
);
CREATE INDEX unit_assignment_access_unit ON assets.unit_assignment_access (tenant_id, unit_id, technician_membership_id);

-- ---------------------------------------------------------------------------------------------
-- devices
-- ---------------------------------------------------------------------------------------------
CREATE TABLE devices.capabilities (              -- model register (FR-A04); one row per version
  id                  uuid NOT NULL,
  version             int NOT NULL,
  tenant_id           uuid NOT NULL,
  manufacturer        text NOT NULL,
  model               text NOT NULL,
  control             boolean NOT NULL,
  mode_control        boolean NOT NULL,
  fan_control         boolean NOT NULL,
  temperature         jsonb,                     -- {min,max,step} or null
  modes               text[] NOT NULL DEFAULT '{}',
  fan_levels          text[] NOT NULL DEFAULT '{}',
  ventilation         boolean NOT NULL DEFAULT false,
  ventilation_levels  text[] NOT NULL DEFAULT '{}',
  sensors             jsonb NOT NULL DEFAULT '[]',
  firmware_candidates text[] NOT NULL DEFAULT '{}',
  is_current          boolean NOT NULL DEFAULT true,
  created_at          timestamptz NOT NULL DEFAULT platform.app_now(),
  PRIMARY KEY (id, version)
);
CREATE UNIQUE INDEX capabilities_current ON devices.capabilities (id) WHERE is_current;
CREATE UNIQUE INDEX capabilities_model ON devices.capabilities (tenant_id, lower(manufacturer), lower(model)) WHERE is_current;

CREATE TABLE devices.devices (
  id                        uuid PRIMARY KEY DEFAULT gen_random_uuid(),
  tenant_id                 uuid NOT NULL,
  serial                    text NOT NULL,
  iot_thing_name            text UNIQUE,         -- AWS IoT Core thing
  certificate_arn           text,
  binding_id                uuid,
  unit_id                   uuid,                -- current binding (denormalised)
  target_unit_id            uuid NOT NULL,
  created_by_membership_id  uuid NOT NULL,
  connection                text NOT NULL DEFAULT 'unknown' CHECK (connection IN ('online','offline','unknown','connecting','error')),
  last_seen_at              timestamptz,
  firmware_version          text NOT NULL,
  power_signal              text NOT NULL DEFAULT 'unknown' CHECK (power_signal IN ('unknown','on','off')),
  tamper                    text NOT NULL DEFAULT 'clear' CHECK (tamper IN ('clear','detected')),
  version                   int NOT NULL DEFAULT 1,
  created_at                timestamptz NOT NULL DEFAULT platform.app_now(),
  updated_at                timestamptz NOT NULL DEFAULT platform.app_now(),
  UNIQUE (tenant_id, id)
);
CREATE UNIQUE INDEX devices_serial ON devices.devices (tenant_id, upper(btrim(serial)));   -- duplicate serial CONFLICT (AT-T11-E)
CREATE INDEX devices_unit ON devices.devices (tenant_id, unit_id);

CREATE TABLE devices.sensors (
  id                  uuid PRIMARY KEY DEFAULT gen_random_uuid(),
  tenant_id           uuid NOT NULL,
  device_id           uuid NOT NULL,
  metric              text NOT NULL,
  unit                text NOT NULL,
  boundary_id         text,
  stale_after_seconds int NOT NULL DEFAULT 120 CHECK (stale_after_seconds > 0),
  calibrated_at       timestamptz,
  FOREIGN KEY (tenant_id, device_id) REFERENCES devices.devices(tenant_id, id),
  UNIQUE (device_id, metric)
);

CREATE TABLE devices.device_bindings (
  id              uuid PRIMARY KEY DEFAULT gen_random_uuid(),
  tenant_id       uuid NOT NULL,
  device_id       uuid NOT NULL,
  unit_id         uuid NOT NULL,
  customer_org_id uuid NOT NULL,
  bound_at        timestamptz NOT NULL,
  unbound_at      timestamptz,
  reason          text,
  actor_membership_id uuid NOT NULL,
  FOREIGN KEY (tenant_id, device_id) REFERENCES devices.devices(tenant_id, id)
);
CREATE UNIQUE INDEX device_bindings_active_device ON devices.device_bindings (device_id) WHERE unbound_at IS NULL;
CREATE UNIQUE INDEX device_bindings_active_unit ON devices.device_bindings (unit_id) WHERE unbound_at IS NULL;

CREATE TABLE devices.device_operations (
  id             uuid PRIMARY KEY DEFAULT gen_random_uuid(),
  tenant_id      uuid NOT NULL,
  device_id      uuid NOT NULL,
  unit_id        uuid,
  job_id         uuid,
  kind           text NOT NULL CHECK (kind IN ('check','calibrate','firmware')),
  status         text NOT NULL CHECK (status IN ('queued','running','succeeded','failed')),
  target_version text,
  campaign_id    uuid,
  iot_job_id     text,
  failure_code   text,
  started_at     timestamptz,
  finished_at    timestamptz,
  expires_at     timestamptz NOT NULL,
  actor_membership_id uuid,
  version        int NOT NULL DEFAULT 1,
  created_at     timestamptz NOT NULL DEFAULT platform.app_now(),
  updated_at     timestamptz NOT NULL DEFAULT platform.app_now(),
  FOREIGN KEY (tenant_id, device_id) REFERENCES devices.devices(tenant_id, id)
);
CREATE UNIQUE INDEX device_operations_one_firmware ON devices.device_operations (device_id) WHERE kind = 'firmware' AND status IN ('queued','running');
CREATE INDEX device_operations_device ON devices.device_operations (tenant_id, device_id, created_at DESC);

CREATE TABLE devices.device_events (
  id               uuid PRIMARY KEY DEFAULT gen_random_uuid(),
  tenant_id        uuid NOT NULL,
  device_id        uuid NOT NULL,
  unit_id          uuid,
  event_type       text NOT NULL CHECK (event_type IN ('communication_lost','power_lost','tamper','restored','operation_failed')),
  evidence_source  text NOT NULL CHECK (evidence_source IN ('heartbeat','power_signal','tamper_signal')),
  recovery         jsonb,
  alert_ids        uuid[] NOT NULL DEFAULT '{}',
  sequence         bigint NOT NULL,
  occurred_at      timestamptz NOT NULL,
  restored_at      timestamptz,
  version          int NOT NULL DEFAULT 1,
  created_at       timestamptz NOT NULL DEFAULT platform.app_now(),
  FOREIGN KEY (tenant_id, device_id) REFERENCES devices.devices(tenant_id, id),
  UNIQUE (device_id, sequence)
);
CREATE INDEX device_events_device ON devices.device_events (tenant_id, device_id, occurred_at DESC);

CREATE TABLE devices.device_event_notes (        -- devices.addResponseNote (FR-T12)
  id           uuid PRIMARY KEY DEFAULT gen_random_uuid(),
  tenant_id    uuid NOT NULL,
  event_id     uuid NOT NULL REFERENCES devices.device_events(id),
  actor_id     uuid NOT NULL,
  message      text NOT NULL CHECK (length(message) BETWEEN 1 AND 1000),   -- DD-T12 responseNote 1–1000
  created_at   timestamptz NOT NULL DEFAULT platform.app_now()
);

CREATE TABLE devices.calibration_records (
  id              uuid PRIMARY KEY DEFAULT gen_random_uuid(),
  tenant_id       uuid NOT NULL,
  device_id       uuid NOT NULL,
  sensor_id       uuid NOT NULL REFERENCES devices.sensors(id),
  metric          text NOT NULL,
  unit            text NOT NULL,
  reference_value double precision NOT NULL,
  measured_value  double precision NOT NULL,
  calibrated_at   timestamptz NOT NULL,
  actor_id        uuid NOT NULL,
  job_id          uuid,
  created_at      timestamptz NOT NULL DEFAULT platform.app_now()
);
CREATE INDEX calibration_records_device ON devices.calibration_records (tenant_id, device_id, calibrated_at DESC);

CREATE TABLE devices.firmware_campaigns (        -- FR-A20
  id                         uuid PRIMARY KEY DEFAULT gen_random_uuid(),
  tenant_id                  uuid NOT NULL,
  model_id                   uuid NOT NULL,
  from_versions              text[] NOT NULL,
  target_version             text NOT NULL,
  checksum                   text NOT NULL,
  waves                      jsonb NOT NULL,     -- [{label, percent}]
  window_start_local         time NOT NULL,
  window_end_local           time NOT NULL,
  auto_pause_failure_percent int NOT NULL CHECK (auto_pause_failure_percent BETWEEN 1 AND 50),   -- IR111 / DD-A20
  start_at                   timestamptz NOT NULL,
  state                      text NOT NULL CHECK (state IN ('scheduled','running','paused','aborted','completed')),
  reason                     text,
  version                    int NOT NULL DEFAULT 1,
  created_at                 timestamptz NOT NULL DEFAULT platform.app_now(),
  updated_at                 timestamptz NOT NULL DEFAULT platform.app_now()
);

CREATE TABLE devices.firmware_campaign_devices (
  campaign_id  uuid NOT NULL REFERENCES devices.firmware_campaigns(id),
  device_id    uuid NOT NULL REFERENCES devices.devices(id),
  tenant_id    uuid NOT NULL,
  wave         int NOT NULL,
  result       text NOT NULL DEFAULT 'pending' CHECK (result IN ('pending','installing','succeeded','failed','skipped')),
  operation_id uuid REFERENCES devices.device_operations(id),
  detail       text,
  PRIMARY KEY (campaign_id, device_id)
);

-- ---------------------------------------------------------------------------------------------
-- control
-- ---------------------------------------------------------------------------------------------
CREATE TABLE control.commands (
  id                  uuid PRIMARY KEY DEFAULT gen_random_uuid(),
  tenant_id           uuid NOT NULL,
  unit_id             uuid NOT NULL,
  device_id           uuid,
  actor_membership_id uuid NOT NULL,             -- system-restriction / automation memberships for system paths
  source              text NOT NULL CHECK (source IN ('ui','voice','automation','restriction','diagnostic','group')),
  action              jsonb NOT NULL,            -- UnitAction | RestrictionAction
  diagnostic_run_id   uuid,
  job_id              uuid,
  restriction_id      uuid,
  reason              text,
  status              text NOT NULL CHECK (status IN ('requested','sent','acknowledged','failed','expired','cancelled')),
  delivery            text NOT NULL DEFAULT 'not_sent' CHECK (delivery IN ('not_sent','sent')),
  requested_at        timestamptz NOT NULL,
  sent_at             timestamptz,
  acknowledged_at     timestamptz,
  expires_at          timestamptz NOT NULL,
  failure_code        text,
  late_ack_at         timestamptz,               -- ack received after expires_at (recorded, not success)
  observed_state      jsonb,
  correlation_id      text NOT NULL,
  version             int NOT NULL DEFAULT 1,
  created_at          timestamptz NOT NULL DEFAULT platform.app_now(),
  updated_at          timestamptz NOT NULL DEFAULT platform.app_now(),
  CHECK (expires_at > requested_at)
);
CREATE INDEX commands_unit ON control.commands (tenant_id, unit_id, requested_at DESC);
CREATE UNIQUE INDEX commands_one_pending_per_unit ON control.commands (unit_id) WHERE status IN ('requested','sent') AND source <> 'restriction';
CREATE INDEX commands_open_expiry ON control.commands (expires_at) WHERE status IN ('requested','sent');

CREATE TABLE control.diagnostic_runs (           -- FR-T10
  id                  uuid PRIMARY KEY DEFAULT gen_random_uuid(),
  tenant_id           uuid NOT NULL,
  job_id              uuid NOT NULL,
  unit_id             uuid NOT NULL,
  actor_membership_id uuid NOT NULL,
  start_action        jsonb NOT NULL,
  end_action          jsonb NOT NULL,
  duration_minutes    int NOT NULL CHECK (duration_minutes BETWEEN 1 AND 15),
  reason              text NOT NULL CHECK (length(reason) BETWEEN 1 AND 1000),   -- DD-T10
  state               text NOT NULL CHECK (state IN ('awaiting_start','running','end_requested','completed','start_failed','end_failed','end_blocked')),
  start_command_id    uuid NOT NULL REFERENCES control.commands(id),
  end_command_id      uuid REFERENCES control.commands(id),
  started_at          timestamptz,
  end_at              timestamptz,
  failure_code        text,
  version             int NOT NULL DEFAULT 1,
  created_at          timestamptz NOT NULL DEFAULT platform.app_now(),
  updated_at          timestamptz NOT NULL DEFAULT platform.app_now()
);
CREATE INDEX diagnostic_runs_job ON control.diagnostic_runs (tenant_id, job_id);

CREATE TABLE control.automations (               -- customer rules (FR-C04/C05): schedule | event
  id                    uuid PRIMARY KEY DEFAULT gen_random_uuid(),
  tenant_id             uuid NOT NULL,
  customer_org_id       uuid NOT NULL,
  kind                  text NOT NULL CHECK (kind IN ('schedule','event')),
  name                  text NOT NULL CHECK (length(name) BETWEEN 1 AND 120),
  owner_membership_id   uuid NOT NULL,
  created_by_user_id    uuid NOT NULL,
  timezone              text NOT NULL,
  enabled               boolean NOT NULL DEFAULT true,
  priority              int NOT NULL DEFAULT 0,
  disabled_reason       text CHECK (disabled_reason IN ('capability_changed','unit_archived','consent_revoked')),
  definition            jsonb NOT NULL,          -- schedule: weekdays/startLocal/endLocal/endsNextDay/actions; event: condition/action
  version               int NOT NULL DEFAULT 1,
  created_at            timestamptz NOT NULL DEFAULT platform.app_now(),
  updated_at            timestamptz NOT NULL DEFAULT platform.app_now(),
  UNIQUE (tenant_id, id)
);

CREATE TABLE control.automation_units (
  tenant_id     uuid NOT NULL,
  automation_id uuid NOT NULL,
  unit_id       uuid NOT NULL,
  PRIMARY KEY (automation_id, unit_id),
  FOREIGN KEY (tenant_id, automation_id) REFERENCES control.automations(tenant_id, id) ON DELETE CASCADE
);
CREATE INDEX automation_units_unit ON control.automation_units (tenant_id, unit_id);

CREATE TABLE control.automation_policies (       -- HQ automation policies (FR-A11, Policy kind=automation)
  id                  uuid PRIMARY KEY DEFAULT gen_random_uuid(),
  tenant_id           uuid NOT NULL,
  name                text NOT NULL,
  owner_membership_id uuid NOT NULL,
  created_by_user_id  uuid NOT NULL,
  timezone            text NOT NULL,
  enabled             boolean NOT NULL DEFAULT true,
  priority            int NOT NULL DEFAULT 0,
  disabled_reason     text,
  condition           jsonb NOT NULL,
  action              jsonb NOT NULL,
  version             int NOT NULL DEFAULT 1,
  created_at          timestamptz NOT NULL DEFAULT platform.app_now(),
  updated_at          timestamptz NOT NULL DEFAULT platform.app_now(),
  UNIQUE (tenant_id, id)
);

CREATE TABLE control.automation_policy_units (
  tenant_id  uuid NOT NULL,
  policy_id  uuid NOT NULL,
  unit_id    uuid NOT NULL,
  PRIMARY KEY (policy_id, unit_id),
  FOREIGN KEY (tenant_id, policy_id) REFERENCES control.automation_policies(tenant_id, id) ON DELETE CASCADE
);

CREATE TABLE control.automation_runs (           -- trigger log: fired / skipped with reason (DEC-09)
  id             uuid PRIMARY KEY DEFAULT gen_random_uuid(),
  tenant_id      uuid NOT NULL,
  rule_kind      text NOT NULL CHECK (rule_kind IN ('automation','automation_policy')),
  rule_id        uuid NOT NULL,
  unit_id        uuid NOT NULL,
  trigger_ref    text NOT NULL,                  -- schedule tick or event id
  outcome        text NOT NULL CHECK (outcome IN ('command_created','skipped')),
  skip_reason    text,
  command_id     uuid REFERENCES control.commands(id),
  occurred_at    timestamptz NOT NULL,
  UNIQUE (rule_id, unit_id, trigger_ref)
);

CREATE TABLE control.evaluation_events (         -- automations.fire results per tenant/eventId/phase (D02 replay, IR152)
  tenant_id   uuid NOT NULL,
  event_id    uuid NOT NULL,
  phase       text NOT NULL CHECK (phase IN ('schedule_start','schedule_end','condition')),
  occurred_at timestamptz NOT NULL,
  input_hash  text NOT NULL,
  result      jsonb NOT NULL,
  created_at  timestamptz NOT NULL DEFAULT platform.app_now(),
  PRIMARY KEY (tenant_id, event_id, phase)
);
CREATE INDEX evaluation_events_tick ON control.evaluation_events (tenant_id, occurred_at);

-- ---------------------------------------------------------------------------------------------
-- monitoring
-- ---------------------------------------------------------------------------------------------
CREATE TABLE monitoring.alert_policies (         -- Policy kind alert | default_alert (FR-C15, FR-A05)
  id                       uuid PRIMARY KEY DEFAULT gen_random_uuid(),
  tenant_id                uuid NOT NULL,
  kind                     text NOT NULL CHECK (kind IN ('alert','default_alert')),
  customer_id              uuid,
  name                     text NOT NULL,
  owner_membership_id      uuid NOT NULL,
  created_by_user_id       uuid NOT NULL,
  timezone                 text NOT NULL,
  enabled                  boolean NOT NULL DEFAULT true,
  priority                 int NOT NULL DEFAULT 0,
  condition                jsonb,                -- AlertCondition (kind = alert)
  rules                    jsonb,                -- DefaultAlertRule[] (kind = default_alert)
  recipient_membership_ids uuid[] NOT NULL DEFAULT '{}',
  channels                 text[] NOT NULL DEFAULT '{inApp}',
  escalate_after_minutes   int,
  cooldown_minutes         int,
  version                  int NOT NULL DEFAULT 1,
  created_at               timestamptz NOT NULL DEFAULT platform.app_now(),
  updated_at               timestamptz NOT NULL DEFAULT platform.app_now(),
  CHECK ((kind = 'alert' AND customer_id IS NOT NULL AND condition IS NOT NULL)
      OR (kind = 'default_alert' AND customer_id IS NULL AND rules IS NOT NULL)),
  UNIQUE (tenant_id, id)
);
CREATE UNIQUE INDEX alert_policies_one_default ON monitoring.alert_policies (tenant_id) WHERE kind = 'default_alert';
CREATE INDEX alert_policies_customer ON monitoring.alert_policies (tenant_id, customer_id);

CREATE TABLE monitoring.default_rule_settings (  -- per customer on/off (owner-only from the customer app, IR115)
  id                       uuid PRIMARY KEY DEFAULT gen_random_uuid(),
  tenant_id                uuid NOT NULL,
  policy_id                uuid NOT NULL,
  rule_key                 text NOT NULL,
  customer_id              uuid NOT NULL,
  enabled                  boolean NOT NULL,
  changed_by_membership_id uuid NOT NULL,
  reason                   text,
  version                  int NOT NULL DEFAULT 1,
  created_at               timestamptz NOT NULL DEFAULT platform.app_now(),
  updated_at               timestamptz NOT NULL DEFAULT platform.app_now(),
  FOREIGN KEY (tenant_id, policy_id) REFERENCES monitoring.alert_policies(tenant_id, id),
  UNIQUE (policy_id, rule_key, customer_id)
);

CREATE TABLE monitoring.alerts (
  id                  uuid PRIMARY KEY DEFAULT gen_random_uuid(),
  tenant_id           uuid NOT NULL,
  unit_id             uuid NOT NULL,
  customer_org_id     uuid NOT NULL,
  policy_id           uuid,
  rule_key            text,
  type                text NOT NULL CHECK (type IN ('sensor','quality','maintenance','tamper','reconciliation_required')),
  severity            text NOT NULL CHECK (severity IN ('critical','warning','normal')),
  status              text NOT NULL CHECK (status IN ('open','acknowledged','resolved')),
  cause_code          text NOT NULL CHECK (cause_code IN ('window_open','insulation_loss','unknown')),
  evidence_kind       text NOT NULL CHECK (evidence_kind IN ('demo_observation','inferred','inspection')),
  evidence_text       text NOT NULL,
  evidence_ids        uuid[] NOT NULL DEFAULT '{}',
  observed_at         timestamptz NOT NULL,
  detected_at         timestamptz NOT NULL,
  acknowledged_at     timestamptz,
  resolved_at         timestamptz,
  resolution_reason   text,
  resolution_evidence_ids uuid[] NOT NULL DEFAULT '{}',   -- DD-T07 remeasurement / confirmation records
  acknowledged_by     uuid,
  resolved_by         uuid,
  previous_alert_id   uuid REFERENCES monitoring.alerts(id),
  delivery_failures   jsonb NOT NULL DEFAULT '[]',
  version             int NOT NULL DEFAULT 1,
  created_at          timestamptz NOT NULL DEFAULT platform.app_now(),
  updated_at          timestamptz NOT NULL DEFAULT platform.app_now()
);
CREATE INDEX alerts_open ON monitoring.alerts (tenant_id, customer_org_id, severity, detected_at DESC) WHERE status <> 'resolved';
CREATE INDEX alerts_unit ON monitoring.alerts (tenant_id, unit_id, detected_at DESC);
CREATE UNIQUE INDEX alerts_one_open_per_rule ON monitoring.alerts (unit_id, coalesce(policy_id, '00000000-0000-0000-0000-000000000000'::uuid), coalesce(rule_key, ''), type) WHERE status <> 'resolved';

CREATE TABLE monitoring.ventilation_logs (       -- manual record (FR-C07, IR110)
  id                     uuid PRIMARY KEY DEFAULT gen_random_uuid(),
  tenant_id              uuid NOT NULL,
  space_id               uuid NOT NULL,
  unit_id                uuid,
  method                 text NOT NULL CHECK (method IN ('window_opened','door_opened','ventilation_fan','other')),
  duration_minutes       int NOT NULL CHECK (duration_minutes BETWEEN 1 AND 240),  -- IR110
  co2_at_log             jsonb,
  logged_by_membership_id uuid NOT NULL,
  logged_at              timestamptz NOT NULL,
  version                int NOT NULL DEFAULT 1,
  created_at             timestamptz NOT NULL DEFAULT platform.app_now(),
  updated_at             timestamptz NOT NULL DEFAULT platform.app_now()
);
CREATE INDEX ventilation_logs_space ON monitoring.ventilation_logs (tenant_id, space_id, logged_at DESC);

CREATE TABLE monitoring.allergen_observations (  -- DEC-57 / IR98 source rows for AirSeries.allergenObservation
  id             uuid PRIMARY KEY DEFAULT gen_random_uuid(),
  tenant_id      uuid NOT NULL,
  unit_id        uuid NOT NULL,
  availability   text NOT NULL CHECK (availability IN ('not_measured','unsupported','available')),
  substance      text,
  value          double precision,
  unit           text,
  source_label   text,
  observed_at    timestamptz,
  evidence_text  text,
  created_at     timestamptz NOT NULL DEFAULT platform.app_now(),
  CHECK (availability <> 'available' OR (substance IS NOT NULL AND source_label IS NOT NULL AND observed_at IS NOT NULL AND evidence_text IS NOT NULL)),
  CHECK (availability <> 'unsupported' OR (substance IS NULL AND value IS NULL AND unit IS NULL AND source_label IS NULL AND observed_at IS NULL AND evidence_text IS NULL))
);
CREATE INDEX allergen_observations_unit ON monitoring.allergen_observations (tenant_id, unit_id, observed_at DESC NULLS LAST, created_at DESC);

-- Telemetry hot store: 35 days, daily partitions managed by pg_partman (database-design §6)
CREATE TABLE monitoring.alert_notifications (    -- notifications requested for alerts (IR191): the policy cooldown
  tenant_id       uuid NOT NULL,
  notification_id uuid PRIMARY KEY,
  alert_id        uuid NOT NULL,
  policy_id       uuid,
  unit_id         uuid NOT NULL,
  occurred_at     timestamptz NOT NULL
);
CREATE INDEX alert_notifications_policy ON monitoring.alert_notifications (policy_id, unit_id, occurred_at DESC);

CREATE TABLE monitoring.measurements (
  tenant_id      uuid NOT NULL,
  unit_id        uuid NOT NULL,
  sensor_id      uuid NOT NULL,
  metric         text NOT NULL,
  observed_at    timestamptz NOT NULL,
  sequence       bigint NOT NULL,
  value          double precision,
  unit           text NOT NULL,
  raw_unit       text,
  origin         text NOT NULL CHECK (origin IN ('measured','estimated','inspection')),
  quality        text NOT NULL CHECK (quality IN ('valid','missing','stale','suspect')),
  quality_reason text,
  boundary_id    text,
  received_at    timestamptz NOT NULL,
  event_id       uuid NOT NULL,
  PRIMARY KEY (sensor_id, observed_at, sequence)
) PARTITION BY RANGE (observed_at);
CREATE INDEX measurements_unit_metric ON monitoring.measurements (unit_id, metric, observed_at DESC);
CREATE INDEX measurements_observed_brin ON monitoring.measurements USING brin (observed_at);
-- Example partitions; production partitions are created ahead by pg_partman (premake 7, retention 35 days).
CREATE TABLE monitoring.measurements_default PARTITION OF monitoring.measurements DEFAULT;

CREATE TABLE monitoring.measurements_15m (       -- 3 years
  tenant_id    uuid NOT NULL,
  unit_id      uuid NOT NULL,
  metric       text NOT NULL,
  bucket_start timestamptz NOT NULL,
  avg_value    double precision,
  min_value    double precision,
  max_value    double precision,
  energy_kwh   double precision,                 -- metric = power only
  valid_count  int NOT NULL,
  expected_count int NOT NULL,
  PRIMARY KEY (unit_id, metric, bucket_start)
) PARTITION BY RANGE (bucket_start);
CREATE TABLE monitoring.measurements_15m_default PARTITION OF monitoring.measurements_15m DEFAULT;

CREATE TABLE monitoring.measurements_1h (        -- 7 years (energy and MRV evidence)
  tenant_id    uuid NOT NULL,
  unit_id      uuid NOT NULL,
  metric       text NOT NULL,
  bucket_start timestamptz NOT NULL,
  avg_value    double precision,
  min_value    double precision,
  max_value    double precision,
  energy_kwh   double precision,
  valid_count  int NOT NULL,
  expected_count int NOT NULL,
  PRIMARY KEY (unit_id, metric, bucket_start)
) PARTITION BY RANGE (bucket_start);
CREATE TABLE monitoring.measurements_1h_default PARTITION OF monitoring.measurements_1h DEFAULT;

-- ---------------------------------------------------------------------------------------------
-- maintenance
-- ---------------------------------------------------------------------------------------------
CREATE TABLE maintenance.plans (                 -- periodic plans (FR-A06)
  id                uuid PRIMARY KEY DEFAULT gen_random_uuid(),
  tenant_id         uuid NOT NULL,
  unit_id           uuid NOT NULL,
  interval_months   int NOT NULL CHECK (interval_months BETWEEN 1 AND 12),   -- D16
  anchor_day        int NOT NULL CHECK (anchor_day BETWEEN 1 AND 31),        -- UTC day of nextDueAt (D16)
  timezone          text NOT NULL DEFAULT 'UTC',
  next_due_at       timestamptz NOT NULL,
  version           int NOT NULL DEFAULT 1,
  created_at        timestamptz NOT NULL DEFAULT platform.app_now(),
  updated_at        timestamptz NOT NULL DEFAULT platform.app_now(),
  UNIQUE (tenant_id, id)
);

CREATE TABLE maintenance.jobs (
  id                     uuid PRIMARY KEY DEFAULT gen_random_uuid(),
  tenant_id              uuid NOT NULL,
  unit_id                uuid NOT NULL,
  customer_org_id        uuid NOT NULL,
  plan_id                uuid,
  occurrence_at          timestamptz,
  type                   text NOT NULL CHECK (type IN ('periodic','reactive','preventive')),
  status                 text NOT NULL CHECK (status IN ('requested','offered','accepted','assigned','in_progress','submitted','completed','rework_requested','cancelled','on_hold')),
  origin                 text NOT NULL CHECK (origin IN ('client_request','periodic_plan')),
  symptom                text NOT NULL DEFAULT '',
  contact_window         text,
  requested_slot         tstzrange NOT NULL,
  preferred_slots        jsonb NOT NULL DEFAULT '[]',   -- Slot[3] per round (IR113)
  preference_round       int NOT NULL DEFAULT 1,
  scheduled_slot         tstzrange,
  due_at                 timestamptz NOT NULL,
  started_at             timestamptz,
  completed_at           timestamptz,
  contractor_org_id      uuid,
  assignment_id          uuid,
  draft_report_version   int,
  costs                  jsonb NOT NULL DEFAULT '[]',
  follow_up_of_job_id    uuid REFERENCES maintenance.jobs(id),
  follow_up_class        text CHECK (follow_up_class IN ('pending','rework','new_request')),
  follow_up_reason       text,
  time_on_site           jsonb,
  rating                 jsonb,
  customer_confirmed_at  timestamptz,
  warranty_claims        jsonb NOT NULL DEFAULT '[]',
  hold_reason            text,
  version                int NOT NULL DEFAULT 1,
  created_at             timestamptz NOT NULL DEFAULT platform.app_now(),
  updated_at             timestamptz NOT NULL DEFAULT platform.app_now(),
  FOREIGN KEY (tenant_id, plan_id) REFERENCES maintenance.plans(tenant_id, id),
  UNIQUE (tenant_id, id),
  UNIQUE (plan_id, occurrence_at)
);
CREATE INDEX jobs_status ON maintenance.jobs (tenant_id, status, due_at);
CREATE INDEX jobs_unit ON maintenance.jobs (tenant_id, unit_id, created_at DESC);
CREATE INDEX jobs_customer ON maintenance.jobs (tenant_id, customer_org_id, created_at DESC);
CREATE INDEX jobs_contractor ON maintenance.jobs (tenant_id, contractor_org_id, status) WHERE contractor_org_id IS NOT NULL;
CREATE INDEX jobs_follow_up_pending ON maintenance.jobs (tenant_id, created_at) WHERE follow_up_class = 'pending';

CREATE TABLE maintenance.job_alerts (
  tenant_id uuid NOT NULL,
  job_id    uuid NOT NULL,
  alert_id  uuid NOT NULL,
  PRIMARY KEY (job_id, alert_id),
  FOREIGN KEY (tenant_id, job_id) REFERENCES maintenance.jobs(tenant_id, id)
);

CREATE TABLE maintenance.slot_proposals (        -- HQ / contractor proposals to the client (IR113)
  id               uuid PRIMARY KEY DEFAULT gen_random_uuid(),
  tenant_id        uuid NOT NULL,
  job_id           uuid NOT NULL,
  source           text NOT NULL CHECK (source IN ('hq','contractor')),
  slot             tstzrange NOT NULL,
  hold             jsonb NOT NULL,
  message          text NOT NULL,
  reply_by         timestamptz NOT NULL,
  status           text NOT NULL CHECK (status IN ('pending','accepted','declined','withdrawn','expired')),
  decided_at       timestamptz,
  decline_reason   text CHECK (decline_reason IN ('not_home','too_late','other')),
  decline_comment  text,
  created_at       timestamptz NOT NULL DEFAULT platform.app_now(),
  FOREIGN KEY (tenant_id, job_id) REFERENCES maintenance.jobs(tenant_id, id)
);
CREATE UNIQUE INDEX slot_proposals_one_pending ON maintenance.slot_proposals (job_id) WHERE status = 'pending';

CREATE TABLE maintenance.offers (
  id                 uuid PRIMARY KEY DEFAULT gen_random_uuid(),
  tenant_id          uuid NOT NULL,
  job_id             uuid NOT NULL,
  contractor_org_id  uuid NOT NULL,
  terms_version      text NOT NULL,
  visit_slot         tstzrange NOT NULL,
  offered_at         timestamptz NOT NULL,
  offer_expires_at   timestamptz NOT NULL,
  access_valid_from  timestamptz NOT NULL,
  access_valid_until timestamptz NOT NULL,
  decision           text CHECK (decision IN ('accept','decline')),
  decided_by         uuid,
  decided_at         timestamptz,
  decline_reason     text,
  expired_at         timestamptz,                  -- set by the worker when IR48 returns the job; decision stays null
  version            int NOT NULL DEFAULT 1,
  created_at         timestamptz NOT NULL DEFAULT platform.app_now(),
  updated_at         timestamptz NOT NULL DEFAULT platform.app_now(),
  FOREIGN KEY (tenant_id, job_id) REFERENCES maintenance.jobs(tenant_id, id)
);
CREATE UNIQUE INDEX offers_one_open ON maintenance.offers (job_id) WHERE decision IS NULL AND expired_at IS NULL;
CREATE INDEX offers_contractor ON maintenance.offers (tenant_id, contractor_org_id, offered_at DESC);

CREATE TABLE maintenance.partner_slot_proposals (
  id                        uuid PRIMARY KEY DEFAULT gen_random_uuid(),
  tenant_id                 uuid NOT NULL,
  offer_id                  uuid NOT NULL REFERENCES maintenance.offers(id),
  slot                      tstzrange NOT NULL,
  technician_membership_id  uuid NOT NULL,
  reason                    text NOT NULL,
  sent_at                   timestamptz NOT NULL,
  status                    text NOT NULL CHECK (status IN ('pending','sent_to_client','kept','approved','declined','withdrawn'))
);

CREATE TABLE maintenance.assignments (
  id                        uuid PRIMARY KEY DEFAULT gen_random_uuid(),
  tenant_id                 uuid NOT NULL,
  job_id                    uuid NOT NULL,
  technician_membership_id  uuid NOT NULL,
  valid_from                timestamptz NOT NULL,
  valid_until               timestamptz NOT NULL,
  scheduled                 tstzrange NOT NULL,
  status                    text NOT NULL CHECK (status IN ('active','revoked')),
  reason                    text,
  acknowledgement           text NOT NULL DEFAULT 'pending' CHECK (acknowledgement IN ('pending','accepted','cant_make')),
  acknowledged_at           timestamptz,
  cant_make_reason          text,
  alternative_slot          tstzrange,
  version                   int NOT NULL DEFAULT 1,
  created_at                timestamptz NOT NULL DEFAULT platform.app_now(),
  updated_at                timestamptz NOT NULL DEFAULT platform.app_now(),
  FOREIGN KEY (tenant_id, job_id) REFERENCES maintenance.jobs(tenant_id, id)
);

CREATE UNIQUE INDEX assignments_one_active ON maintenance.assignments (job_id) WHERE status = 'active';
CREATE INDEX assignments_technician ON maintenance.assignments (tenant_id, technician_membership_id, lower(scheduled)) WHERE status = 'active';
-- A technician cannot hold two overlapping active assignments (CONFLICT, FR-P03)
ALTER TABLE maintenance.assignments ADD CONSTRAINT assignments_no_overlap
  EXCLUDE USING gist (technician_membership_id WITH =, scheduled WITH &&) WHERE (status = 'active');

-- Change capture into the outbox (IR186): every insert / update / delete of an Offer or Assignment publishes its access
-- snapshot for equipment's projection, in the same transaction and in commit-safe outbox order.
CREATE FUNCTION maintenance.publish_access() RETURNS trigger LANGUAGE plpgsql AS $$
DECLARE
  r record;
  unit uuid;
  payload jsonb;
BEGIN
  IF TG_OP = 'DELETE' THEN r := OLD; ELSE r := NEW; END IF;
  SELECT j.unit_id INTO unit FROM maintenance.jobs j WHERE j.id = r.job_id;
  IF TG_TABLE_NAME = 'offers' THEN
    payload := jsonb_build_object('offerId', r.id, 'jobId', r.job_id, 'unitId', unit, 'contractorOrgId', r.contractor_org_id,
      'accepted', TG_OP <> 'DELETE' AND r.decision IS NOT DISTINCT FROM 'accept',
      'accessValidFrom', r.access_valid_from, 'accessValidUntil', r.access_valid_until);
    INSERT INTO platform.outbox (tenant_id, aggregate_type, aggregate_id, event_type, payload, correlation_id)
      VALUES (r.tenant_id, 'offer', r.id, 'OfferAccessChanged', payload, 'change-capture');
  ELSE
    payload := jsonb_build_object('assignmentId', r.id, 'jobId', r.job_id, 'unitId', unit, 'technicianMembershipId', r.technician_membership_id,
      'deleted', TG_OP = 'DELETE', 'active', TG_OP <> 'DELETE' AND r.status = 'active', 'createdAt', r.created_at,
      'scheduledFrom', lower(r.scheduled), 'scheduledUntil', upper(r.scheduled));
    INSERT INTO platform.outbox (tenant_id, aggregate_type, aggregate_id, event_type, payload, correlation_id)
      VALUES (r.tenant_id, 'assignment', r.id, 'AssignmentAccessChanged', payload, 'change-capture');
  END IF;
  RETURN NULL;
END $$;
CREATE TRIGGER offers_publish_access AFTER INSERT OR DELETE OR UPDATE OF job_id, contractor_org_id, decision, access_valid_from, access_valid_until ON maintenance.offers
  FOR EACH ROW EXECUTE FUNCTION maintenance.publish_access();
CREATE TRIGGER assignments_publish_access AFTER INSERT OR DELETE OR UPDATE OF job_id, technician_membership_id, status, scheduled, created_at ON maintenance.assignments
  FOR EACH ROW EXECUTE FUNCTION maintenance.publish_access();

CREATE TABLE maintenance.work_reports (          -- one row per report version; versions are immutable once submitted
  id                  uuid NOT NULL,
  version             int NOT NULL,
  tenant_id           uuid NOT NULL,
  job_id              uuid NOT NULL,
  author_id           uuid NOT NULL,
  state               text NOT NULL CHECK (state IN ('draft','submitted','accepted','returned')),
  items               jsonb NOT NULL DEFAULT '[]',   -- InspectionItem[] (18 components at submit, IR100)
  measurements        jsonb NOT NULL DEFAULT '[]',
  parts               jsonb NOT NULL DEFAULT '[]',
  refrigerant         jsonb NOT NULL DEFAULT '[]',
  sign_off            jsonb,
  work_text           text NOT NULL DEFAULT '',
  next_action         jsonb,
  review_availability text NOT NULL DEFAULT 'pending',
  submitted_at        timestamptz,
  accepted_at         timestamptz,
  created_at          timestamptz NOT NULL DEFAULT platform.app_now(),
  updated_at          timestamptz NOT NULL DEFAULT platform.app_now(),
  PRIMARY KEY (id, version),
  FOREIGN KEY (tenant_id, job_id) REFERENCES maintenance.jobs(tenant_id, id)
);
CREATE INDEX work_reports_job ON maintenance.work_reports (tenant_id, job_id, version DESC);
CREATE UNIQUE INDEX work_reports_one_draft ON maintenance.work_reports (job_id) WHERE state = 'draft';

CREATE TABLE maintenance.report_reviews (
  id               uuid PRIMARY KEY DEFAULT gen_random_uuid(),
  tenant_id        uuid NOT NULL,
  report_id        uuid NOT NULL,
  report_version   int NOT NULL,
  reviewer_user_id uuid NOT NULL,
  decision         text NOT NULL CHECK (decision IN ('accept','return')),
  reason           text,
  occurred_at      timestamptz NOT NULL,
  FOREIGN KEY (report_id, report_version) REFERENCES maintenance.work_reports(id, version),
  UNIQUE (report_id, report_version)
);

CREATE TABLE maintenance.attachments (
  id          uuid PRIMARY KEY DEFAULT gen_random_uuid(),
  tenant_id   uuid NOT NULL,
  job_id      uuid NOT NULL,
  report_id   uuid,
  object_key  text NOT NULL UNIQUE,              -- S3 key
  name        text NOT NULL,
  mime        text NOT NULL CHECK (mime IN ('image/jpeg','image/png')),
  size_bytes  int NOT NULL CHECK (size_bytes BETWEEN 1 AND 10485760),
  status      text NOT NULL CHECK (status IN ('processing','ready','failed')),
  scan_result text,
  uploaded_by uuid NOT NULL,
  created_at  timestamptz NOT NULL DEFAULT platform.app_now(),
  updated_at  timestamptz NOT NULL DEFAULT platform.app_now(),
  FOREIGN KEY (tenant_id, job_id) REFERENCES maintenance.jobs(tenant_id, id)
);

CREATE TABLE maintenance.job_notes (
  id          uuid PRIMARY KEY DEFAULT gen_random_uuid(),
  tenant_id   uuid NOT NULL,
  job_id      uuid NOT NULL,
  author_id   uuid NOT NULL,
  visibility  text NOT NULL CHECK (visibility IN ('internal','customer')),
  message     text NOT NULL CHECK (length(message) BETWEEN 1 AND 2000),
  created_at  timestamptz NOT NULL DEFAULT platform.app_now(),
  FOREIGN KEY (tenant_id, job_id) REFERENCES maintenance.jobs(tenant_id, id)
);

CREATE TABLE maintenance.job_events (            -- job history (jobs.events)
  id             uuid PRIMARY KEY DEFAULT gen_random_uuid(),
  tenant_id      uuid NOT NULL,
  job_id         uuid NOT NULL,
  actor_user_id  uuid,
  action         text NOT NULL,
  note_id        uuid REFERENCES maintenance.job_notes(id),
  report_id      uuid,
  report_version int,
  occurred_at    timestamptz NOT NULL,
  FOREIGN KEY (tenant_id, job_id) REFERENCES maintenance.jobs(tenant_id, id)
);
CREATE INDEX job_events_job ON maintenance.job_events (tenant_id, job_id, occurred_at);

CREATE TABLE maintenance.job_history_snapshots (   -- IR23/IR24 JobHistorySnapshot frozen once when access ends (IR124)
  id                 uuid PRIMARY KEY DEFAULT gen_random_uuid(),
  tenant_id          uuid NOT NULL,
  job_id             uuid NOT NULL,
  owner_kind         text NOT NULL CHECK (owner_kind IN ('organization','membership')),
  owner_id           uuid NOT NULL,                 -- contractor organization or technician membership
  owner_user_id      uuid,                          -- technician user bound to the history (IR23 PV-005)
  as_of              timestamptz NOT NULL,
  type               text NOT NULL,
  status             text NOT NULL,
  contractor_org_id  uuid,
  completed_at       timestamptz,
  has_report         boolean NOT NULL,
  acceptance         text NOT NULL CHECK (acceptance IN ('accepted','not_accepted')),
  decision_event_ids uuid[] NOT NULL DEFAULT '{}',
  FOREIGN KEY (tenant_id, job_id) REFERENCES maintenance.jobs(tenant_id, id),
  UNIQUE (job_id, owner_kind, owner_id)
);
CREATE INDEX job_history_owner ON maintenance.job_history_snapshots (tenant_id, owner_kind, owner_id);

CREATE TABLE maintenance.contractors (           -- ContractorProfile (FR-A21)
  id                     uuid PRIMARY KEY DEFAULT gen_random_uuid(),
  tenant_id              uuid NOT NULL,
  organization_id        uuid NOT NULL UNIQUE,
  name                   text NOT NULL,
  status                 text NOT NULL CHECK (status IN ('active','suspended')),
  registration_no        text NOT NULL,
  service_areas          text[] NOT NULL DEFAULT '{}',
  contact_email          citext NOT NULL,
  insurance_valid_until  timestamptz,
  delegation             tstzrange NOT NULL,
  suspended_reason       text,
  version                int NOT NULL DEFAULT 1,
  created_at             timestamptz NOT NULL DEFAULT platform.app_now(),
  updated_at             timestamptz NOT NULL DEFAULT platform.app_now()
);

CREATE TABLE maintenance.rate_cards (
  id                 uuid PRIMARY KEY DEFAULT gen_random_uuid(),
  tenant_id          uuid NOT NULL,
  contractor_org_id  uuid NOT NULL,
  effective_from     timestamptz NOT NULL,
  currency           char(3) NOT NULL CHECK (currency IN ('MYR','USD')),
  lines              jsonb NOT NULL,             -- [{workType, amountMinor, note}]
  version            int NOT NULL DEFAULT 1,
  created_at         timestamptz NOT NULL DEFAULT platform.app_now(),
  UNIQUE (contractor_org_id, effective_from)
);

CREATE TABLE maintenance.certificates (          -- FR-P09
  id                        uuid PRIMARY KEY DEFAULT gen_random_uuid(),
  tenant_id                 uuid NOT NULL,
  membership_id             uuid NOT NULL,
  organization_id           uuid NOT NULL,
  code                      text NOT NULL,
  name                      text NOT NULL,
  number                    text NOT NULL,
  issued_at                 timestamptz NOT NULL,
  expires_at                timestamptz NOT NULL,
  object_key                text,
  file_name                 text,                       -- uploaded document name (Certificate.fileName)
  status                    text NOT NULL CHECK (status IN ('valid','expiring','expired','pending_verification','rejected')),
  rejection_reason          text,
  renewal_of                uuid REFERENCES maintenance.certificates(id),
  verified_by_membership_id uuid,
  verified_at               timestamptz,
  training_requested_at     timestamptz,
  training_request_note     text,                       -- certificates.requestTraining note
  version                   int NOT NULL DEFAULT 1,
  created_at                timestamptz NOT NULL DEFAULT platform.app_now(),
  updated_at                timestamptz NOT NULL DEFAULT platform.app_now()
);
CREATE INDEX certificates_expiry ON maintenance.certificates (tenant_id, organization_id, expires_at);

CREATE TABLE maintenance.unavailability (        -- FR-P06
  id                         uuid PRIMARY KEY DEFAULT gen_random_uuid(),
  tenant_id                  uuid NOT NULL,
  organization_id            uuid NOT NULL,
  membership_id              uuid,
  days                       daterange NOT NULL,
  type                       text NOT NULL CHECK (type IN ('annual_leave','training','public_holiday','sick','other')),
  note                       text,
  conflicting_assignment_ids uuid[] NOT NULL DEFAULT '{}',
  created_at                 timestamptz NOT NULL DEFAULT platform.app_now()
);

CREATE TABLE maintenance.sla_targets (           -- FR-A22
  id                         uuid PRIMARY KEY DEFAULT gen_random_uuid(),
  tenant_id                  uuid NOT NULL,
  plan_type                  text NOT NULL CHECK (plan_type IN ('rto','general','energy','environment')),
  response_hours             int NOT NULL,
  arrival_in_window_percent  numeric(5,2) NOT NULL,
  first_time_fix_percent     numeric(5,2) NOT NULL,
  effective_from             timestamptz NOT NULL,
  version                    int NOT NULL DEFAULT 1,
  UNIQUE (tenant_id, plan_type, effective_from)
);

CREATE TABLE maintenance.filter_care_settings (  -- FR-C18
  id              uuid PRIMARY KEY DEFAULT gen_random_uuid(),
  tenant_id       uuid NOT NULL,
  customer_id     uuid NOT NULL UNIQUE,
  threshold_hours int CHECK (threshold_hours BETWEEN 50 AND 2000),   -- null = model default 250 h (DD-C18)
  fallback_days   int NOT NULL DEFAULT 30 CHECK (fallback_days BETWEEN 7 AND 180),
  recipients      text NOT NULL DEFAULT 'owners' CHECK (recipients IN ('owners','all_users')),
  channels        text[] NOT NULL DEFAULT '{inApp}',
  version         int NOT NULL DEFAULT 1,
  updated_at      timestamptz NOT NULL DEFAULT platform.app_now()
);

CREATE TABLE maintenance.filter_cleanings (
  id                  uuid PRIMARY KEY DEFAULT gen_random_uuid(),
  tenant_id           uuid NOT NULL,
  unit_id             uuid NOT NULL,
  cleaned_at          timestamptz NOT NULL,
  marked_by_membership_id uuid NOT NULL
);
CREATE INDEX filter_cleanings_unit ON maintenance.filter_cleanings (tenant_id, unit_id, cleaned_at DESC);

CREATE TABLE maintenance.parts_catalog (
  code       text PRIMARY KEY,
  tenant_id  uuid NOT NULL,
  name       text NOT NULL,
  active     boolean NOT NULL DEFAULT true
);

-- ---------------------------------------------------------------------------------------------
-- billing
-- ---------------------------------------------------------------------------------------------
CREATE TABLE billing.contracts (
  id                   uuid NOT NULL,
  version              int NOT NULL,             -- every revision is a new row (contract versions, FR-A07)
  tenant_id            uuid NOT NULL,
  customer_id          uuid NOT NULL,
  customer_org_id      uuid NOT NULL,
  plan_type            text NOT NULL CHECK (plan_type IN ('rto','general','energy','environment')),
  term                 tstzrange NOT NULL,
  price_minor          bigint NOT NULL CHECK (price_minor >= 0),
  currency             char(3) NOT NULL CHECK (currency IN ('MYR','USD')),
  restriction_eligible boolean NOT NULL,
  rules_version        text,
  is_current           boolean NOT NULL DEFAULT true,
  created_by           uuid NOT NULL,
  created_at           timestamptz NOT NULL DEFAULT platform.app_now(),
  PRIMARY KEY (id, version)
);
CREATE UNIQUE INDEX contracts_current ON billing.contracts (id) WHERE is_current;
CREATE INDEX contracts_customer ON billing.contracts (tenant_id, customer_id) WHERE is_current;

CREATE TABLE billing.contract_units (
  tenant_id        uuid NOT NULL,
  contract_id      uuid NOT NULL,
  contract_version int NOT NULL,
  unit_id          uuid NOT NULL,
  PRIMARY KEY (contract_id, contract_version, unit_id),
  FOREIGN KEY (contract_id, contract_version) REFERENCES billing.contracts(id, version)
);

CREATE TABLE billing.invoices (
  id                uuid PRIMARY KEY DEFAULT gen_random_uuid(),
  tenant_id         uuid NOT NULL,
  number            text NOT NULL,
  contract_id       uuid NOT NULL,
  contract_version  int NOT NULL,
  customer_id       uuid NOT NULL,
  amount_minor      bigint NOT NULL CHECK (amount_minor > 0),
  currency          char(3) NOT NULL CHECK (currency IN ('MYR','USD')),
  period            tstzrange NOT NULL,
  due_at            timestamptz NOT NULL,
  status            text NOT NULL CHECK (status IN ('unpaid','processing','paid')),
  paid_at           timestamptz,
  last_reminded_at  timestamptz,
  version           int NOT NULL DEFAULT 1,
  created_at        timestamptz NOT NULL DEFAULT platform.app_now(),
  updated_at        timestamptz NOT NULL DEFAULT platform.app_now(),
  FOREIGN KEY (contract_id, contract_version) REFERENCES billing.contracts(id, version),
  UNIQUE (tenant_id, number),
  UNIQUE (contract_id, period)
);
CREATE INDEX invoices_customer ON billing.invoices (tenant_id, customer_id, due_at DESC);
CREATE INDEX invoices_overdue ON billing.invoices (tenant_id, due_at) WHERE status <> 'paid';

CREATE TABLE billing.payments (                  -- Stripe Checkout or manual (FR-C11, FR-A08)
  id                         uuid PRIMARY KEY DEFAULT gen_random_uuid(),
  tenant_id                  uuid NOT NULL,
  invoice_id                 uuid NOT NULL REFERENCES billing.invoices(id),
  amount_minor               bigint NOT NULL CHECK (amount_minor > 0),
  currency                   char(3) NOT NULL,
  method                     text CHECK (method IN ('demo_credit_card','demo_debit_card')),   -- PaymentMethod; null for manual (DD-A08)
  channel                    text NOT NULL CHECK (channel IN ('demo','stripe_checkout','manual')),
  status                     text NOT NULL CHECK (status IN ('initiated','processing','confirmed','failed','expired')),
  stripe_checkout_session_id text UNIQUE,
  stripe_payment_intent_id   text UNIQUE,
  payment_reference          text,
  recorded_by_membership_id  uuid,
  confirmed_at               timestamptz,
  failure_code               text,
  confirmation_reason        text,                 -- payments.confirm / recordManual reason (DD-A08)
  event_ids                  uuid[] NOT NULL DEFAULT '{}',   -- payments.simulate eventIds (idempotent)
  version                    int NOT NULL DEFAULT 1,
  created_at                 timestamptz NOT NULL DEFAULT platform.app_now(),
  updated_at                 timestamptz NOT NULL DEFAULT platform.app_now()
);
CREATE INDEX payments_invoice ON billing.payments (tenant_id, invoice_id, created_at DESC);
CREATE UNIQUE INDEX payments_reference ON billing.payments (tenant_id, payment_reference) WHERE payment_reference IS NOT NULL;   -- unique within tenant (DD-A08)

CREATE TABLE billing.stripe_events (             -- webhook de-duplication and evidence
  id            text PRIMARY KEY,                -- Stripe event id (evt_...)
  type          text NOT NULL,
  livemode      boolean NOT NULL,
  payment_id    uuid REFERENCES billing.payments(id),
  received_at   timestamptz NOT NULL DEFAULT platform.app_now(),
  processed_at  timestamptz,
  payload       jsonb NOT NULL
);

CREATE TABLE billing.inquiries (                 -- FR-C12 / FR-A08
  id              uuid PRIMARY KEY DEFAULT gen_random_uuid(),
  tenant_id       uuid NOT NULL,
  customer_id     uuid NOT NULL,
  invoice_id      uuid REFERENCES billing.invoices(id),
  restriction_id  uuid,
  subject_type    text NOT NULL CHECK (subject_type IN ('payment','restriction')),
  message         text NOT NULL CHECK (length(message) BETWEEN 1 AND 2000),
  state           text NOT NULL CHECK (state IN ('received','answered')),
  reply           text,
  answered_by     uuid,
  answered_at     timestamptz,
  created_by      uuid NOT NULL,
  version         int NOT NULL DEFAULT 1,
  created_at      timestamptz NOT NULL DEFAULT platform.app_now(),
  updated_at      timestamptz NOT NULL DEFAULT platform.app_now()
);

CREATE TABLE billing.payout_statements (         -- FR-A23 / FR-P10
  id                        uuid PRIMARY KEY DEFAULT gen_random_uuid(),
  tenant_id                 uuid NOT NULL,
  contractor_org_id         uuid NOT NULL,
  period                    char(7) NOT NULL,    -- YYYY-MM
  status                    text NOT NULL CHECK (status IN ('draft','approved','paid')),
  currency                  char(3) NOT NULL,
  gross_minor               bigint NOT NULL,
  deductions_minor          bigint NOT NULL,
  net_minor                 bigint NOT NULL,
  pay_date                  date NOT NULL,
  approved_by_membership_id uuid,
  paid_at                   timestamptz,
  version                   int NOT NULL DEFAULT 1,
  created_at                timestamptz NOT NULL DEFAULT platform.app_now(),
  updated_at                timestamptz NOT NULL DEFAULT platform.app_now(),
  UNIQUE (contractor_org_id, period),
  CHECK (net_minor = gross_minor - deductions_minor)
);

CREATE TABLE billing.payout_lines (
  id            uuid PRIMARY KEY DEFAULT gen_random_uuid(),
  statement_id  uuid NOT NULL REFERENCES billing.payout_statements(id) ON DELETE CASCADE,
  tenant_id     uuid NOT NULL,
  job_id        uuid NOT NULL,
  work_type     text NOT NULL,
  accepted_at   timestamptz,
  amount_minor  bigint NOT NULL,
  kind          text NOT NULL CHECK (kind IN ('charge','deduction','adjustment')),
  note          text
);

CREATE TABLE billing.payout_queries (
  id            uuid PRIMARY KEY DEFAULT gen_random_uuid(),
  statement_id  uuid NOT NULL REFERENCES billing.payout_statements(id),
  line_id       uuid REFERENCES billing.payout_lines(id),
  tenant_id     uuid NOT NULL,
  asked_by      uuid NOT NULL,
  topic         text NOT NULL CHECK (topic IN ('amount','deduction','missing_job','other')),
  message       text NOT NULL CHECK (length(message) BETWEEN 1 AND 2000),   -- IR111
  state         text NOT NULL CHECK (state IN ('open','answered','adjusted')),
  resolution    text,                                -- PayoutQuestion.reply
  adjustment_minor bigint,                           -- signed; applied to the next statement (IR137)
  applied_statement_id uuid,                         -- statement that carries the adjustment line
  resolved_by   uuid,
  created_at    timestamptz NOT NULL DEFAULT platform.app_now(),
  resolved_at   timestamptz
);

-- ---------------------------------------------------------------------------------------------
-- restrictions
-- ---------------------------------------------------------------------------------------------
CREATE TABLE restrictions.restrictions (
  id                      uuid PRIMARY KEY DEFAULT gen_random_uuid(),
  tenant_id               uuid NOT NULL,
  contract_id             uuid NOT NULL,
  contract_version        int NOT NULL,
  customer_id             uuid NOT NULL,
  rules_version           text NOT NULL,
  notice_at               timestamptz NOT NULL,
  execute_after           timestamptz NOT NULL,
  reason                  text NOT NULL,
  policy                  jsonb NOT NULL,        -- {kind:temperature_limit,minimumCoolingSetpoint} | {kind:power_off}
  state                   text NOT NULL CHECK (state IN ('scheduled','requested','applied','release_requested','released','cancelled')),
  exception_until         timestamptz,
  exception_reason        text,
  grace_until             timestamptz,
  release_intent          jsonb,                 -- {source,at,actorMembershipId} (IR35)
  recovery_cases          jsonb NOT NULL DEFAULT '[]',
  notice_notification_ids uuid[] NOT NULL DEFAULT '{}',
  version                 int NOT NULL DEFAULT 1,
  created_at              timestamptz NOT NULL DEFAULT platform.app_now(),
  updated_at              timestamptz NOT NULL DEFAULT platform.app_now(),
  CHECK (execute_after >= notice_at + interval '24 hours'),     -- IR05
  UNIQUE (tenant_id, id)
);
CREATE INDEX restrictions_active ON restrictions.restrictions (tenant_id, customer_id) WHERE state NOT IN ('released','cancelled');

CREATE TABLE restrictions.restriction_invoices (  -- cause invoices
  tenant_id      uuid NOT NULL,
  restriction_id uuid NOT NULL,
  invoice_id     uuid NOT NULL,
  PRIMARY KEY (restriction_id, invoice_id),
  FOREIGN KEY (tenant_id, restriction_id) REFERENCES restrictions.restrictions(tenant_id, id)
);
CREATE INDEX restriction_invoices_invoice ON restrictions.restriction_invoices (tenant_id, invoice_id);

CREATE TABLE restrictions.restriction_units (     -- per-unit apply / release state
  tenant_id            uuid NOT NULL,
  restriction_id       uuid NOT NULL,
  unit_id              uuid NOT NULL,
  apply_state          text NOT NULL CHECK (apply_state IN ('not_sent','sent_unknown','applied','not_applied')),
  release_state        text NOT NULL CHECK (release_state IN ('none','waiting_reconcile','requested','released','not_required','failed')),
  apply_command_ids    uuid[] NOT NULL DEFAULT '{}',
  release_command_ids  uuid[] NOT NULL DEFAULT '{}',
  observed_restriction jsonb,
  observed_at          timestamptz,
  evidence_id          uuid,
  pending_reason       text,
  PRIMARY KEY (restriction_id, unit_id),
  FOREIGN KEY (tenant_id, restriction_id) REFERENCES restrictions.restrictions(tenant_id, id)
);

CREATE TABLE restrictions.restriction_commands (  -- the device commands billing requested (IR194): billing's own record
  tenant_id      uuid NOT NULL,
  command_id     uuid PRIMARY KEY,                  -- assigned by billing; equipment stores the command (IR185)
  restriction_id uuid NOT NULL,
  unit_id        uuid NOT NULL,
  kind           text NOT NULL CHECK (kind IN ('apply_restriction','remove_restriction')),
  delivered      boolean NOT NULL,                 -- delivery = sent at request time; undelivered intents can be cancelled
  status         text NOT NULL CHECK (status IN ('requested','acknowledged','failed','expired','cancelled')),  -- requested = open
  requested_at   timestamptz NOT NULL,
  updated_at     timestamptz NOT NULL
);
CREATE INDEX restriction_commands_open ON restrictions.restriction_commands (restriction_id, unit_id) WHERE status = 'requested';
CREATE INDEX restriction_units_unit ON restrictions.restriction_units (tenant_id, unit_id);

-- ---------------------------------------------------------------------------------------------
-- energy
-- ---------------------------------------------------------------------------------------------
CREATE TABLE energy.baselines (
  id            uuid NOT NULL,
  version       int NOT NULL,
  tenant_id     uuid NOT NULL,
  unit_ids      uuid[] NOT NULL,
  period        tstzrange NOT NULL,
  method        text NOT NULL CHECK (method IN ('demo_fixed','demo_period_comparison','measured_period')),
  baseline_kwh  double precision,
  quality       jsonb NOT NULL,
  boundary_id   text NOT NULL,
  boundary      text NOT NULL,
  assumptions   text NOT NULL,
  source        text NOT NULL,
  is_current    boolean NOT NULL DEFAULT true,
  created_by    uuid NOT NULL,
  created_at    timestamptz NOT NULL DEFAULT platform.app_now(),
  PRIMARY KEY (id, version)
);
CREATE UNIQUE INDEX baselines_current ON energy.baselines (id) WHERE is_current;

CREATE TABLE energy.emission_factors (
  id               uuid NOT NULL,
  version          int NOT NULL,
  tenant_id        uuid NOT NULL,
  region           text NOT NULL,
  year             int NOT NULL,
  kg_co2e_per_kwh  numeric(10,6) NOT NULL CHECK (kg_co2e_per_kwh > 0),
  source           text NOT NULL,
  is_current       boolean NOT NULL DEFAULT true,
  created_by       uuid NOT NULL,
  created_at       timestamptz NOT NULL DEFAULT platform.app_now(),
  PRIMARY KEY (id, version)
);
CREATE UNIQUE INDEX emission_factors_current ON energy.emission_factors (tenant_id, region, year) WHERE is_current;

CREATE TABLE energy.mrv_reports (                -- one row per report version (mrv.versions)
  id             uuid NOT NULL,
  version        int NOT NULL,
  tenant_id      uuid NOT NULL,
  organization_id uuid NOT NULL,
  period         tstzrange NOT NULL,
  status         text NOT NULL CHECK (status IN ('draft','demo_reviewed','reviewed')),
  conditions     jsonb NOT NULL,                 -- boundary, baseline and factor snapshots
  results        jsonb NOT NULL,
  evidence_ids   uuid[] NOT NULL DEFAULT '{}',
  created_by     uuid NOT NULL,
  created_at     timestamptz NOT NULL DEFAULT platform.app_now(),
  PRIMARY KEY (id, version)
);

CREATE TABLE energy.mrv_reviews (
  id             uuid PRIMARY KEY DEFAULT gen_random_uuid(),
  tenant_id      uuid NOT NULL,
  report_id      uuid NOT NULL,
  report_version int NOT NULL,
  user_id        uuid NOT NULL,
  comment        text NOT NULL,
  reviewed_at    timestamptz NOT NULL,
  FOREIGN KEY (report_id, report_version) REFERENCES energy.mrv_reports(id, version)
);

CREATE TABLE energy.offset_quotes (
  id                     uuid PRIMARY KEY DEFAULT gen_random_uuid(),
  tenant_id              uuid NOT NULL,
  customer_id            uuid NOT NULL,
  purpose                text NOT NULL,
  amount_kg              numeric(14,3) NOT NULL CHECK (amount_kg > 0),
  period                 tstzrange NOT NULL,
  unit_ids               uuid[] NOT NULL DEFAULT '{}',
  estimated_amount_minor bigint,
  currency               char(3),
  expires_at             timestamptz NOT NULL,
  provider               text NOT NULL DEFAULT 'unselected',
  version                int NOT NULL DEFAULT 1,       -- offsets.simulate(request) carries quoteVersion
  created_at             timestamptz NOT NULL DEFAULT platform.app_now()
);

CREATE TABLE energy.offset_records (
  id                   uuid PRIMARY KEY DEFAULT gen_random_uuid(),
  tenant_id            uuid NOT NULL,
  quote_id             uuid NOT NULL REFERENCES energy.offset_quotes(id),
  customer_id          uuid NOT NULL,
  amount_kg            numeric(14,3) NOT NULL,
  state                text NOT NULL CHECK (state IN ('demo_requested','demo_purchased','demo_retired','failed','requested','purchased','retired')),
  previous_state       text,
  purchase_ref         text,
  retirement_ref       text,
  certificate_ref      text,
  version              int NOT NULL DEFAULT 1,
  created_at           timestamptz NOT NULL DEFAULT platform.app_now(),
  updated_at           timestamptz NOT NULL DEFAULT platform.app_now()
);

CREATE TABLE energy.offset_attempts (
  id           uuid PRIMARY KEY DEFAULT gen_random_uuid(),
  tenant_id    uuid NOT NULL,
  record_id    uuid NOT NULL REFERENCES energy.offset_records(id),
  stage        text NOT NULL CHECK (stage IN ('purchase','retirement')),
  status       text NOT NULL CHECK (status IN ('pending','succeeded','failed')),
  started_at   timestamptz NOT NULL,
  completed_at timestamptz,
  completed_event_id uuid UNIQUE,            -- SR18 eventId of the success/failure event (idempotent replay)
  completed_event    text CHECK (completed_event IN ('purchase_confirm','retire','fail'))
);

-- ---------------------------------------------------------------------------------------------
-- notify
-- ---------------------------------------------------------------------------------------------
CREATE TABLE notify.notifications (
  id                         uuid PRIMARY KEY DEFAULT gen_random_uuid(),
  tenant_id                  uuid NOT NULL,
  recipient_membership_id    uuid NOT NULL,
  scope_version_at_creation  int NOT NULL,
  type                       text NOT NULL,
  channel                    text NOT NULL DEFAULT 'inApp' CHECK (channel IN ('inApp','email','whatsapp')),   -- inApp simulated, email/whatsapp preview (IR04)
  template_key               text NOT NULL CHECK (template_key IN ('alert','quality','schedule_change','report_return','completion','payment','payment_reminder','restriction','inquiry','job_update','device_operation','invite')),
  target                     jsonb NOT NULL,     -- {kind,id}
  params                     jsonb NOT NULL,
  source_alert_id            uuid,
  severity                   text NOT NULL CHECK (severity IN ('critical','warning','normal')),
  occurred_at                timestamptz NOT NULL,
  read_at                    timestamptz,
  version                    int NOT NULL DEFAULT 1,   -- notifications.markRead requires the expected version
  created_at                 timestamptz NOT NULL DEFAULT platform.app_now()
);
CREATE INDEX notifications_inbox ON notify.notifications (tenant_id, recipient_membership_id, occurred_at DESC);
CREATE INDEX notifications_unread ON notify.notifications (recipient_membership_id) WHERE read_at IS NULL;

CREATE TABLE notify.deliveries (
  id               uuid PRIMARY KEY DEFAULT gen_random_uuid(),
  tenant_id        uuid NOT NULL,
  notification_id  uuid NOT NULL REFERENCES notify.notifications(id),
  channel          text NOT NULL CHECK (channel IN ('inApp','email','whatsapp')),
  state            text NOT NULL CHECK (state IN ('queued','sent','delivered','failed','suppressed')),
  provider_message_id text,
  failure_reason   text,
  attempts         int NOT NULL DEFAULT 0,
  updated_at       timestamptz NOT NULL DEFAULT platform.app_now(),
  UNIQUE (notification_id, channel)
);

CREATE TABLE notify.templates (
  key        text NOT NULL,
  channel    text NOT NULL CHECK (channel IN ('inApp','email','whatsapp')),
  locale     text NOT NULL CHECK (locale IN ('en','ms')),
  version    int NOT NULL,
  subject    text,
  body       text NOT NULL,
  provider_template_name text,                    -- WhatsApp approved template
  active     boolean NOT NULL DEFAULT true,
  PRIMARY KEY (key, channel, locale, version)
);

-- ---------------------------------------------------------------------------------------------
-- audit (append-only, monthly partitions, 7 years, monthly export to S3 Object Lock)
-- ---------------------------------------------------------------------------------------------
CREATE TABLE audit.audit_log (
  id                 uuid NOT NULL DEFAULT gen_random_uuid(),
  tenant_id          uuid NOT NULL,
  actor_id           text NOT NULL,              -- user id or system actor (system-demo, system-restriction, system-scheduler)
  actor_role_at_time text NOT NULL CHECK (actor_role_at_time IN ('client','contractor','technician','admin','system')),
  membership_id      uuid,
  action             text NOT NULL,              -- operation name or system transition
  target_kind        text NOT NULL,
  target_id          text NOT NULL,
  previous_version   int,
  next_version       int,
  occurred_at        timestamptz NOT NULL,
  correlation_id     text NOT NULL,
  result             text NOT NULL CHECK (result IN ('success','denied','failed','pending')),
  masked_before      jsonb NOT NULL DEFAULT '{}',
  masked_after       jsonb NOT NULL DEFAULT '{}',
  reason             text,
  source_ip          inet,
  PRIMARY KEY (id, occurred_at)
) PARTITION BY RANGE (occurred_at);
CREATE INDEX audit_target ON audit.audit_log (tenant_id, target_kind, target_id, occurred_at DESC);
CREATE INDEX audit_correlation ON audit.audit_log (tenant_id, correlation_id);
CREATE INDEX audit_actor ON audit.audit_log (tenant_id, actor_id, occurred_at DESC);
CREATE TABLE audit.audit_log_default PARTITION OF audit.audit_log DEFAULT;

CREATE FUNCTION audit.forbid_change() RETURNS trigger LANGUAGE plpgsql AS $$
BEGIN
  RAISE EXCEPTION 'audit.audit_log is append-only';
END $$;
CREATE TRIGGER audit_log_append_only BEFORE UPDATE OR DELETE ON audit.audit_log
  FOR EACH ROW EXECUTE FUNCTION audit.forbid_change();

-- ---------------------------------------------------------------------------------------------
-- Reference copies for the identity domain (IR188, IR194): notify resolves notification targets and recipients from
-- these, identity checks membership scopes and client users with them, instead of the owners' tables. Kept by the identity-api consumer from RowChanged events; same keys as the source.
-- ---------------------------------------------------------------------------------------------
CREATE TABLE notify.ref_units (id uuid PRIMARY KEY, tenant_id uuid NOT NULL, customer_org_id uuid, property_id uuid, display_name text);
CREATE TABLE notify.ref_customers (id uuid PRIMARY KEY, tenant_id uuid NOT NULL, organization_id uuid);
CREATE TABLE notify.ref_jobs (id uuid PRIMARY KEY, tenant_id uuid NOT NULL, unit_id uuid, customer_org_id uuid);
CREATE TABLE notify.ref_offers (id uuid PRIMARY KEY, tenant_id uuid NOT NULL, job_id uuid, contractor_org_id uuid);
CREATE INDEX ref_offers_job ON notify.ref_offers (job_id);
CREATE TABLE notify.ref_assignments (id uuid PRIMARY KEY, tenant_id uuid NOT NULL, job_id uuid, technician_membership_id uuid, status text);
CREATE INDEX ref_assignments_job ON notify.ref_assignments (job_id);
CREATE TABLE notify.ref_invoices (id uuid PRIMARY KEY, tenant_id uuid NOT NULL, number text, customer_id uuid, status text, due_at timestamptz);
CREATE TABLE notify.ref_inquiries (id uuid PRIMARY KEY, tenant_id uuid NOT NULL, customer_id uuid, subject_type text);
CREATE TABLE notify.ref_restrictions (id uuid PRIMARY KEY, tenant_id uuid NOT NULL, customer_id uuid);
CREATE TABLE notify.ref_restriction_units (restriction_id uuid NOT NULL, unit_id uuid NOT NULL, tenant_id uuid NOT NULL, PRIMARY KEY (restriction_id, unit_id));
CREATE TABLE notify.ref_devices (id uuid PRIMARY KEY, tenant_id uuid NOT NULL, serial text, unit_id uuid);
CREATE TABLE notify.ref_properties (id uuid PRIMARY KEY, tenant_id uuid NOT NULL, customer_org_id uuid);  -- identity: membership scopes (IR194)

-- Reference copies for billing (IR194), kept by the billing-api consumer: customer organizations of restrictions and
-- inquiries, and the property of each contract unit (invoices.list propertyId, IR199).
CREATE TABLE billing.ref_customers (id uuid PRIMARY KEY, tenant_id uuid NOT NULL, organization_id uuid);
CREATE TABLE billing.ref_units (id uuid PRIMARY KEY, tenant_id uuid NOT NULL, property_id uuid);
CREATE INDEX ref_units_property ON billing.ref_units (property_id);

-- Reference copies for maintenance (IR192), kept by the maintenance-api consumer: technician planning, partner
-- memberships and the history snapshots of the worker.
CREATE TABLE maintenance.ref_memberships (
  id uuid PRIMARY KEY, tenant_id uuid NOT NULL, version int, created_at timestamptz, updated_at timestamptz, user_id uuid, organization_id uuid,
  role text, employment text, scope_version int, valid_from timestamptz, valid_until timestamptz, client_role text
);
CREATE INDEX ref_memberships_org ON maintenance.ref_memberships (organization_id, role);
CREATE INDEX ref_memberships_user ON maintenance.ref_memberships (user_id);

-- Reference copies for energy (IR189), kept by the energy-api consumer.
CREATE TABLE energy.ref_units (id uuid PRIMARY KEY, tenant_id uuid NOT NULL, customer_org_id uuid, property_id uuid, archived boolean);
CREATE TABLE energy.ref_customers (id uuid PRIMARY KEY, tenant_id uuid NOT NULL, organization_id uuid);
CREATE TABLE energy.ref_properties (id uuid PRIMARY KEY, tenant_id uuid NOT NULL, customer_org_id uuid, archived boolean);
CREATE TABLE energy.ref_organizations (id uuid PRIMARY KEY, tenant_id uuid NOT NULL, kind text);
CREATE TABLE energy.ref_attachments (id uuid PRIMARY KEY, tenant_id uuid NOT NULL);
CREATE TABLE energy.ref_alerts (id uuid PRIMARY KEY, tenant_id uuid NOT NULL, unit_id uuid, detected_at timestamptz);
CREATE INDEX ref_alerts_unit ON energy.ref_alerts (unit_id, detected_at);
CREATE TABLE energy.ref_jobs (id uuid PRIMARY KEY, tenant_id uuid NOT NULL, unit_id uuid, status text, updated_at timestamptz);
CREATE INDEX ref_jobs_unit ON energy.ref_jobs (unit_id, updated_at);
CREATE TABLE energy.ref_power_samples (           -- minute-slot power measurements (D07, IR08, IR11)
  sensor_id uuid NOT NULL, observed_at timestamptz NOT NULL, sequence bigint NOT NULL,
  tenant_id uuid NOT NULL, unit_id uuid, value double precision, unit text, origin text, quality text, boundary_id text, event_id uuid,
  PRIMARY KEY (sensor_id, observed_at, sequence)
);
CREATE INDEX ref_power_samples_unit ON energy.ref_power_samples (unit_id, observed_at);

CREATE TRIGGER units_capture AFTER INSERT OR DELETE OR UPDATE OF customer_org_id, property_id, display_name, archived ON assets.units
  FOR EACH ROW EXECUTE FUNCTION platform.capture_row('id', 'tenant_id', 'customer_org_id', 'property_id', 'display_name', 'archived');
CREATE TRIGGER memberships_capture AFTER INSERT OR DELETE OR UPDATE ON identity.memberships
  FOR EACH ROW EXECUTE FUNCTION platform.capture_row('id', 'tenant_id', 'version', 'created_at', 'updated_at', 'user_id', 'organization_id', 'role', 'employment',
    'scope_version', 'valid_from', 'valid_until', 'client_role');
CREATE TRIGGER customers_capture AFTER INSERT OR DELETE OR UPDATE OF organization_id ON assets.customers
  FOR EACH ROW EXECUTE FUNCTION platform.capture_row('id', 'tenant_id', 'organization_id');
CREATE TRIGGER jobs_capture AFTER INSERT OR DELETE OR UPDATE OF unit_id, customer_org_id, status, updated_at ON maintenance.jobs
  FOR EACH ROW EXECUTE FUNCTION platform.capture_row('id', 'tenant_id', 'unit_id', 'customer_org_id', 'status', 'updated_at');
CREATE TRIGGER properties_capture AFTER INSERT OR DELETE OR UPDATE OF customer_org_id, archived ON assets.properties
  FOR EACH ROW EXECUTE FUNCTION platform.capture_row('id', 'tenant_id', 'customer_org_id', 'archived');
CREATE TRIGGER organizations_capture AFTER INSERT OR DELETE OR UPDATE OF kind ON identity.organizations
  FOR EACH ROW EXECUTE FUNCTION platform.capture_row('id', 'tenant_id', 'kind');
CREATE TRIGGER attachments_capture AFTER INSERT OR DELETE ON maintenance.attachments
  FOR EACH ROW EXECUTE FUNCTION platform.capture_row('id', 'tenant_id');
CREATE TRIGGER alerts_capture AFTER INSERT OR DELETE OR UPDATE OF unit_id, detected_at ON monitoring.alerts
  FOR EACH ROW EXECUTE FUNCTION platform.capture_row('id', 'tenant_id', 'unit_id', 'detected_at');
-- minute-slot power samples only (D07): the rows energy integrates; measurements are insert-only
CREATE TRIGGER measurements_capture AFTER INSERT ON monitoring.measurements
  FOR EACH ROW WHEN (NEW.metric = 'power' AND NEW.observed_at = date_trunc('minute', NEW.observed_at))
  EXECUTE FUNCTION platform.capture_row('sensor_id', 'observed_at', 'sequence', 'tenant_id', 'unit_id', 'value', 'unit', 'origin', 'quality', 'boundary_id', 'event_id');
CREATE TRIGGER offers_capture AFTER INSERT OR DELETE OR UPDATE OF job_id, contractor_org_id ON maintenance.offers
  FOR EACH ROW EXECUTE FUNCTION platform.capture_row('id', 'tenant_id', 'job_id', 'contractor_org_id');
CREATE TRIGGER assignments_capture AFTER INSERT OR DELETE OR UPDATE OF job_id, technician_membership_id, status ON maintenance.assignments
  FOR EACH ROW EXECUTE FUNCTION platform.capture_row('id', 'tenant_id', 'job_id', 'technician_membership_id', 'status');
CREATE TRIGGER invoices_capture AFTER INSERT OR DELETE OR UPDATE OF number, customer_id, status, due_at ON billing.invoices
  FOR EACH ROW EXECUTE FUNCTION platform.capture_row('id', 'tenant_id', 'number', 'customer_id', 'status', 'due_at');
CREATE TRIGGER inquiries_capture AFTER INSERT OR DELETE OR UPDATE OF customer_id, subject_type ON billing.inquiries
  FOR EACH ROW EXECUTE FUNCTION platform.capture_row('id', 'tenant_id', 'customer_id', 'subject_type');
CREATE TRIGGER restrictions_capture AFTER INSERT OR DELETE OR UPDATE OF customer_id ON restrictions.restrictions
  FOR EACH ROW EXECUTE FUNCTION platform.capture_row('id', 'tenant_id', 'customer_id');
CREATE TRIGGER restriction_units_capture AFTER INSERT OR DELETE ON restrictions.restriction_units
  FOR EACH ROW EXECUTE FUNCTION platform.capture_row('restriction_id', 'unit_id', 'tenant_id');
CREATE TRIGGER devices_capture AFTER INSERT OR DELETE OR UPDATE OF serial, unit_id ON devices.devices
  FOR EACH ROW EXECUTE FUNCTION platform.capture_row('id', 'tenant_id', 'serial', 'unit_id');

-- ---------------------------------------------------------------------------------------------
-- Row-level security: every business table with tenant_id. platform.* is infrastructure read across
-- tenants by the outbox relay and scheduler, which then SET LOCAL app.tenant_id per item.
-- ---------------------------------------------------------------------------------------------
DO $$
DECLARE r record;
BEGIN
  FOR r IN
    SELECT c.table_schema, c.table_name
    FROM information_schema.columns c
    JOIN pg_class pc ON pc.relname = c.table_name
    JOIN pg_namespace pn ON pn.oid = pc.relnamespace AND pn.nspname = c.table_schema
    WHERE c.column_name = 'tenant_id'
      AND c.table_schema IN ('identity','assets','devices','control','monitoring','maintenance','billing','restrictions','energy','notify','audit')
      AND pc.relkind IN ('r','p')
      AND NOT pc.relispartition
  LOOP
    EXECUTE format('ALTER TABLE %I.%I ENABLE ROW LEVEL SECURITY', r.table_schema, r.table_name);
    EXECUTE format('ALTER TABLE %I.%I FORCE ROW LEVEL SECURITY', r.table_schema, r.table_name);
    EXECUTE format($p$CREATE POLICY tenant_isolation ON %I.%I
                     USING (tenant_id = current_setting('app.tenant_id', true)::uuid)
                     WITH CHECK (tenant_id = current_setting('app.tenant_id', true)::uuid)$p$,
                   r.table_schema, r.table_name);
  END LOOP;
END $$;

-- ---------------------------------------------------------------------------------------------
-- Roles (created by the migration owner; passwords come from Secrets Manager / IAM auth)
-- ---------------------------------------------------------------------------------------------
DO $$
BEGIN
  IF NOT EXISTS (SELECT 1 FROM pg_roles WHERE rolname = 'ac_app') THEN CREATE ROLE ac_app NOLOGIN; END IF;
  IF NOT EXISTS (SELECT 1 FROM pg_roles WHERE rolname = 'ac_worker') THEN CREATE ROLE ac_worker NOLOGIN; END IF;
  IF NOT EXISTS (SELECT 1 FROM pg_roles WHERE rolname = 'ac_readonly') THEN CREATE ROLE ac_readonly NOLOGIN; END IF;
END $$;
GRANT USAGE ON SCHEMA platform, identity, assets, devices, control, monitoring, maintenance, billing, restrictions, energy, notify, audit TO ac_app, ac_worker, ac_readonly;
GRANT SELECT, INSERT, UPDATE, DELETE ON ALL TABLES IN SCHEMA platform, identity, assets, devices, control, monitoring, maintenance, billing, restrictions, energy, notify TO ac_app, ac_worker;
GRANT SELECT, INSERT ON ALL TABLES IN SCHEMA audit TO ac_app, ac_worker;
GRANT SELECT ON ALL TABLES IN SCHEMA platform, identity, assets, devices, control, monitoring, maintenance, billing, restrictions, energy, notify, audit TO ac_readonly;
-- Least privilege per business-domain service (IR194): each service role reaches only its own schemas and the shared
-- infrastructure (platform); the append-only audit log belongs to identity (IR196: other services publish
-- AuditRecorded). ac_app stays for tools and the all-domain development scheduler. Reference copies live in the
-- consumer's own schema (ref_*).
DO $$
DECLARE
  d record;
BEGIN
  FOR d IN SELECT * FROM (VALUES
      ('ac_svc_identity',    ARRAY['identity','notify']),
      ('ac_svc_equipment',   ARRAY['assets','devices','control','monitoring']),
      ('ac_svc_maintenance', ARRAY['maintenance']),
      ('ac_svc_billing',     ARRAY['billing','restrictions']),
      ('ac_svc_energy',      ARRAY['energy'])) AS v(role, schemas)
  LOOP
    IF NOT EXISTS (SELECT 1 FROM pg_roles WHERE rolname = d.role) THEN
      EXECUTE format('CREATE ROLE %I NOLOGIN', d.role);
    END IF;
    EXECUTE format('GRANT USAGE ON SCHEMA platform, %s TO %I', array_to_string(d.schemas, ', '), d.role);
    EXECUTE format('GRANT SELECT, INSERT, UPDATE, DELETE ON ALL TABLES IN SCHEMA platform, %s TO %I', array_to_string(d.schemas, ', '), d.role);
  END LOOP;
  GRANT USAGE ON SCHEMA audit TO ac_svc_identity;
  GRANT SELECT, INSERT ON ALL TABLES IN SCHEMA audit TO ac_svc_identity;
END $$;
-- Later migrations: ALTER DEFAULT PRIVILEGES in each schema grants the same rights on new tables.

